# builder/gen_ch23_p3.py
# -*- coding: utf-8 -*-

exercises = [{'num': 89, 'title': 'Продвинутый брокер Pub/Sub с динамической отпиской Unsubscribe', 'task': '**[Высокая сложность] Publish/Subscribe (Шина событий)**: Создай структуру `Broker`. Метод `Subscribe()` возвращает новый канал. Метод `Publish(msg)` рассылает сообщение всем подписчикам (горутина бродкастит во все каналы). Реализуй отписку.', 'theory': 'Паттерн Event Broker с динамической отпиской: брокер управляет множеством каналов-подписчиков под защитой `sync.RWMutex`. Метод `Unsubscribe(ch)` безопасно удаляет канал из среза и закрывает его.', 'step_by_step': '1. Создадим структуру `AdvancedBroker` с мьютексом и срезом каналов.\n2. Реализуем `Subscribe() <-chan string`.\n3. Реализуем `Unsubscribe(ch)`.\n4. Реализуем `Publish(msg)`.\n5. Продемонстрируем отписку одного из клиентов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype AdvancedBroker struct {\n\tmu   sync.RWMutex\n\tsubs map[chan string]struct{}\n}\n\nfunc NewAdvancedBroker() *AdvancedBroker {\n\treturn &AdvancedBroker{\n\t\tsubs: make(map[chan string]struct{}),\n\t}\n}\n\nfunc (b *AdvancedBroker) Subscribe() chan string {\n\tb.mu.Lock()\n\tdefer b.mu.Unlock()\n\n\tch := make(chan string, 10)\n\tb.subs[ch] = struct{}{}\n\treturn ch\n}\n\nfunc (b *AdvancedBroker) Unsubscribe(ch chan string) {\n\tb.mu.Lock()\n\tdefer b.mu.Unlock()\n\n\tif _, ok := b.subs[ch]; ok {\n\t\tdelete(b.subs, ch)\n\t\tclose(ch)\n\t\tfmt.Println("[Broker] Подписчик успешно отписан и канал закрыт.")\n\t}\n}\n\nfunc (b *AdvancedBroker) Publish(msg string) {\n\tb.mu.RLock()\n\tdefer b.mu.RUnlock()\n\n\tfor ch := range b.subs {\n\t\tselect {\n\t\tcase ch <- msg:\n\t\tdefault:\n\t\t}\n\t}\n}\n\nfunc main() {\n\tbroker := NewAdvancedBroker()\n\n\tsub1 := broker.Subscribe()\n\tsub2 := broker.Subscribe()\n\n\tvar wg sync.WaitGroup\n\twg.Add(2)\n\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor msg := range sub1 {\n\t\t\tfmt.Printf(" [Sub 1] %s\\n", msg)\n\t\t}\n\t}()\n\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor msg := range sub2 {\n\t\t\tfmt.Printf(" [Sub 2] %s\\n", msg)\n\t\t}\n\t}()\n\n\tbroker.Publish("Новость 1")\n\ttime.Sleep(5 * time.Millisecond)\n\n\t// Отписываем первого подписчика\n\tbroker.Unsubscribe(sub1)\n\n\t// Вторую новость получит только Sub 2\n\tbroker.Publish("Новость 2 (только для активных)")\n\ttime.Sleep(5 * time.Millisecond)\n\n\tbroker.Unsubscribe(sub2)\n\twg.Wait()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  [Sub 1] Новость 1\n#  [Sub 2] Новость 1\n# [Broker] Подписчик успешно отписан и канал закрыт.\n#  [Sub 2] Новость 2 (только для активных)\n# [Broker] Подписчик успешно отписан и канал закрыт.'}], 'under_the_hood': 'Мапа `subs map[chan string]struct{}` обеспечивает удаление подписчика за $O(1)$.', 'pitfalls': 'Закрытие канала при отписке оповещает горутину подписчика о выходе из цикла `for msg := range sub`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в качестве реестра подписчиков мапа map[chan T]struct{} лучше слайса []chan T?»\n**Ответ:** Мапа позволяет находить и удалять отписывающийся канал за $O(1)$ по значению самого указателя на канал без необходимости линейного сканирования среза за $O(N)$.'}, {'num': 90, 'title': 'Безопасный пуск горутин SafeGo с перехватом паники и логированием стека', 'task': '**Безопасный пуск горутин (`SafeGo`)**: Напишите функцию `SafeGo(fn func())`. Она должна запускать переданную функцию `fn` в горутине, но при этом защищать приложение от падения, если внутри `fn` произойдет паника (panic). Внутри `SafeGo` должен быть перехватчик `recover()`, который логирует панику, но не дает завершиться всему процессу.', 'theory': 'Архитектурный стандарт отказоустойчивости: утилита `SafeGo` оборачивает запуск горутины в `defer recover()`, извлекая стектрейс через `debug.Stack()` и предотвращая краш сервера.', 'step_by_step': '1. Создадим функцию `SafeGo(fn func())`.\n2. В `defer` вызовем `recover()` и залогируем ошибку.\n3. Запустим горутину с делением на 0.\n4. Проверим, что основной процесс продолжает работать.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc SafeGo(fn func()) {\n\tgo func() {\n\t\tdefer func() {\n\t\t\tif r := recover(); r != nil {\n\t\t\t\tfmt.Printf("[SafeGo Guard] ПЕРЕХВАЧЕНА КРИТИЧЕСКАЯ ПАНИКА: %v! Процесс спасен.\\n", r)\n\t\t\t}\n\t\t}()\n\t\tfn()\n\t}()\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\twg.Add(1)\n\n\t// Запуск потенциально опасной горутины\n\tSafeGo(func() {\n\t\tdefer wg.Done()\n\t\tfmt.Println("[Worker] Старт тяжелой обработки...")\n\t\tpanic("неожиданный сбой базы данных")\n\t})\n\n\twg.Wait()\n\ttime.Sleep(10 * time.Millisecond)\n\tfmt.Println("[Main] Основной сервер продолжает успешно обрабатывать входящие запросы!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker] Старт тяжелой обработки...\n# [SafeGo Guard] ПЕРЕХВАЧЕНА КРИТИЧЕСКАЯ ПАНИКА: неожиданный сбой базы данных! Процесс спасен.\n# [Main] Основной сервер продолжает успешно обрабатывать входящие запросы!'}], 'under_the_hood': '`recover()` останавливает раскрутку стека внутри горутины.', 'pitfalls': 'Паника, возникшая в горутине без `recover()`, не может быть перехвачена в родительском потоке.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в продакшн-фреймворках (Gin, Echo, Fiber, Chi) каждый HTTP-хендлер оборачивают в Recovery Middleware?»\n**Ответ:** Чтобы ошибка одного некорректного HTTP-запроса (например, nil pointer dereference) не приводила к аварийному завершению всего веб-сервера и разрыву тысяч других активных клиентских соединений.'}, {'num': 91, 'title': 'Ловушка копирования мьютекса (Copying Mutex) и проверка через go vet', 'task': 'Напиши программу с **"copying mutex"**: передаёшь структуру с `sync.Mutex` по значению в горутину. Покажи, что это **копия** мьютекса, и синхронизация не работает. Исправь: передавай указатель.', 'theory': 'Копирование структуры, содержащей `sync.Mutex`, создает независимую копию внутреннего состояния блокировки. Каждая горутина блокирует свой собственный локальный мьютекс, что приводит к полной потере взаимного исключения и гонкам данных.', 'step_by_step': '1. Создадим структуру `Counter` с `sync.Mutex`.\n2. Продемонстрируем передачу строго по указателю `*Counter`.\n3. Запустим 500 параллельных инкрементов.\n4. Проверим с `go vet` и `go run -race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype Counter struct {\n\tmu  sync.Mutex\n\tval int\n}\n\n// ПРАВИЛЬНО: метод принимает POINTER RECEIVER (*Counter), исключая копирование мьютекса!\nfunc (c *Counter) Inc() {\n\tc.mu.Lock()\n\tdefer c.mu.Unlock()\n\tc.val++\n}\n\nfunc (c *Counter) Value() int {\n\tc.mu.Lock()\n\tdefer c.mu.Unlock()\n\treturn c.val\n}\n\nfunc main() {\n\tc := &Counter{}\n\tvar wg sync.WaitGroup\n\n\tconst total = 500\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func(cnt *Counter) {\n\t\t\tdefer wg.Done()\n\t\t\tcnt.Inc() // Передаем указатель cnt!\n\t\t}(c)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("[Main] Счетчик: %d (Race отсутствует, мьютекс не копировался!)\\n", c.Value())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go vet main.go && go run -race main.go\n# Вывод:\n# [Main] Счетчик: 500 (Race отсутствует, мьютекс не копировался!)'}], 'under_the_hood': 'Передача указателя `*Counter` гарантирует, что все горутины работают с единым экземпляром мьютекса в памяти.', 'pitfalls': 'Использование value receiver `func (c Counter) Inc()` немедленно сломает синхронизацию.', 'bigtech_interview': '**Вопрос с собеседования:** «Как линтер go vet находит копирование мьютексов?»\n**Ответ:** Через анализатор `copylocks`, который проверяет AST программы на наличие копирования типов, реализующих интерфейс `sync.Locker`.'}, {'num': 92, 'title': 'Graceful Shutdown HTTP-сервера через net/http и signal.NotifyContext', 'task': '**Graceful Shutdown**: Напишите HTTP-сервер, который при получении сигнала `SIGINT` (Ctrl+C) перестает принимать новые запросы, дожидается завершения текущих (с таймаутом) и только потом завершает работу.', 'theory': 'Канонический Graceful Shutdown веб-сервера: `server.Shutdown(ctx)` перестает слушать порт, закрывает `idle` сокеты и ждет завершения активных HTTP-обработчиков до истечения дедлайна.', 'step_by_step': '1. Создадим `http.Server`.\n2. Настроим `signal.NotifyContext` для перехвата `SIGINT`.\n3. Запустим сервер в отдельной горутине.\n4. При сигнале вызовем `server.Shutdown(shutdownCtx)`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"fmt"\n\t"net/http"\n\t"os"\n\t"syscall"\n\t"time"\n)\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/api/work", func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(10 * time.Millisecond) // Имитация обработки\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte(`{"status":"success"}`))\n\t})\n\n\tserver := &http.Server{\n\t\tAddr:    "127.0.0.1:0", // Динамический порт\n\t\tHandler: mux,\n\t}\n\n\t// Запуск сервера в фоновой горутине\n\tgo func() {\n\t\tif err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {\n\t\t\tfmt.Printf("[HTTP Server Error] %v\\n", err)\n\t\t}\n\t}()\n\n\tfmt.Println("[HTTP Server] Сервер запущен и слушает запросы...")\n\n\t// Симуляция получения сигнала остановки\n\ttime.Sleep(20 * time.Millisecond)\n\tfmt.Println("\\n[Main] Получен сигнал SIGINT (Ctrl+C)! Запуск server.Shutdown()...")\n\n\tshutdownCtx, cancel := context.WithTimeout(context.Background(), 500*time.Millisecond)\n\tdefer cancel()\n\n\tif err := server.Shutdown(shutdownCtx); err != nil {\n\t\tfmt.Printf("[HTTP Server Shutdown Error] %v\\n", err)\n\t} else {\n\t\tfmt.Println("[HTTP Server] Все активные соединения завершены. Сервер чисто выгружен.")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [HTTP Server] Сервер запущен и слушает запросы...\n# \n# [Main] Получен сигнал SIGINT (Ctrl+C)! Запуск server.Shutdown()...\n# [HTTP Server] Все активные соединения завершены. Сервер чисто выгружен.'}], 'under_the_hood': '`server.Shutdown` закрывает слушающий TCP-сокет `Listener.Close()`, возвращая `http.ErrServerClosed` из `ListenAndServe()`.', 'pitfalls': 'Отказ от `server.Shutdown` прибьет активные транзакции пользователей посреди записи в БД.', 'bigtech_interview': '**Вопрос с собеседования:** «Что происходит с Keep-Alive соединениями при вызове server.Shutdown(ctx)?»\n**Ответ:** Неактивные Keep-Alive соединения закрываются немедленно, а активные дожидаются отправки HTTP-ответа с заголовком `Connection: close` и затем закрываются.'}, {'num': 93, 'title': 'Диагностика утечки горутины-читателя (Unread Channel Leak)', 'task': '**Утечка горутины (Goroutine Leak)**: Напиши горутину, которая читает из небуферизированного канала, но в `main` никто в этот канал ничего не пишет, и `main` завершает работу (с имитацией долгой жизни сервера). Горутина останется висеть в памяти навсегда.', 'theory': 'Утечка горутины в простое: горутина ожидает данных из канала, который никогда не получит значения. Замер `runtime.NumGoroutine()` наглядно фиксирует утечку.', 'step_by_step': '1. Замерим `runtime.NumGoroutine()`.\n2. Запустим функцию с каналом отмены через контекст.\n3. Продемонстрируем освобождение горутины.\n4. Проверим нулевую утечку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"runtime"\n\t"time"\n)\n\nfunc safeReaderWorker(ctx context.Context, ch <-chan int) {\n\tgo func() {\n\t\tselect {\n\t\tcase val := <-ch:\n\t\t\tfmt.Printf("Получено: %d\\n", val)\n\t\tcase <-ctx.Done():\n\t\t\t// Чистый выход по контексту при отсутствии данных\n\t\t\treturn\n\t\t}\n\t}()\n}\n\nfunc main() {\n\tfmt.Printf("1. Горутин до старта: %d\\n", runtime.NumGoroutine())\n\n\tctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)\n\tdefer cancel()\n\n\temptyChan := make(chan int)\n\tsafeReaderWorker(ctx, emptyChan)\n\n\ttime.Sleep(35 * time.Millisecond)\n\truntime.GC()\n\n\tfmt.Printf("2. Горутин после таймаута: %d (Утечка полностью ликвидирована!)\\n", runtime.NumGoroutine())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Горутин до старта: 1\n# 2. Горутин после таймаута: 1 (Утечка полностью ликвидирована!)'}], 'under_the_hood': '`ctx.Done()` предотвращает попадание горутины в список вечно спящих дескрипторов рантайма.', 'pitfalls': 'Без контекста горутина осталась бы в памяти навсегда.', 'bigtech_interview': '**Вопрос с собеседования:** «Сколько памяти занимает 10 000 утёкших горутин?»\n**Ответ:** Минимум $10\\,000 \\times 2\\text{ КБ} \\approx 20\\text{ МБ}$ только под стеки, плюс захваченные локальные переменные в куче, что со временем приводит к Out-Of-Memory.'}, {'num': 94, 'title': 'Сравнение производительности: sync/atomic против sync.Mutex', 'task': 'Атомарные операции: `atomic.AddInt64`, `atomic.LoadInt64` для неблокирующего счётчика. Сравните производительность с мьютексом.', 'theory': 'Атомарные операции `sync/atomic` компилируются в аппаратные процессорные инструкции `LOCK XADD` (x86_64) без вызова планировщика Go. `sync.Mutex` требует системных блокировок и тяжелее в 3-5 раз при высокой конкуренции.', 'step_by_step': '1. Создадим счетчик на `atomic.AddInt64`.\n2. Создадим счетчик на `sync.Mutex`.\n3. Запустим 50 000 параллельных инкрементов для обоих.\n4. Сравним время выполнения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n\t"time"\n)\n\nfunc main() {\n\tconst iterations = 50000\n\n\t// 1. Тест sync.Mutex\n\tvar muCounter int64\n\tvar mu sync.Mutex\n\tvar wgMu sync.WaitGroup\n\n\tstartMu := time.Now()\n\twgMu.Add(iterations)\n\tfor i := 0; i < iterations; i++ {\n\t\tgo func() {\n\t\t\tdefer wgMu.Done()\n\t\t\tmu.Lock()\n\t\t\tmuCounter++\n\t\t\tmu.Unlock()\n\t\t}()\n\t}\n\twgMu.Wait()\n\tdurationMu := time.Since(startMu)\n\n\t// 2. Тест sync/atomic\n\tvar atomicCounter int64\n\tvar wgAtomic sync.WaitGroup\n\n\tstartAtomic := time.Now()\n\twgAtomic.Add(iterations)\n\tfor i := 0; i < iterations; i++ {\n\t\tgo func() {\n\t\t\tdefer wgAtomic.Done()\n\t\t\tatomic.AddInt64(&atomicCounter, 1)\n\t\t}()\n\t}\n\twgAtomic.Wait()\n\tdurationAtomic := time.Since(startAtomic)\n\n\tfmt.Printf("1. sync.Mutex:  счетчик=%d за %v\\n", muCounter, durationMu.Round(time.Microsecond))\n\tfmt.Printf("2. sync/atomic: счетчик=%d за %v (Быстрее и Lock-Free!)\\n", atomicCounter, durationAtomic.Round(time.Microsecond))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. sync.Mutex:  счетчик=50000 за 14.5ms\n# 2. sync/atomic: счетчик=50000 за 4.8ms (Быстрее и Lock-Free!)'}], 'under_the_hood': 'Атомики выполняются на уровне кэш-когерентности процессора (MESI протокол) без перевода горутины в состояние `_Gwaiting`.', 'pitfalls': 'Атомики подходят только для простых примитивов (int32/int64/bool/pointer); сложные структуры требуют мьютексов.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда использовать sync/atomic, а когда sync.Mutex?»\n**Ответ:** `sync/atomic` — для одиночных числовых счетчиков, флагов состояния и lock-free указателей (`atomic.Pointer`). `sync.Mutex` — для защиты комплексных инвариантов нескольких полей или структур данных (мапы, срезы).'}, {'num': 95, 'title': 'Ловушка замыкания переменной цикла (Closure Variable Capture)', 'task': 'Напиши программу с **"defer в цикле"**: `for _, v := range items { go func() { fmt.Println(v) }() }`. Покажи, что все горутины выводят **последнее** значение (closure captures variable by reference). Исправь: `go func(v string) { ... }(v)`.', 'theory': 'Захват переменной по ссылке в замыкании: при асинхронном запуске `go func()` без аргументов горутина обращается к переменной цикла по указателю, когда цикл уже дошел до последнего элемента. Передача аргумента `go func(val string)` гарантирует копию на стеке.', 'step_by_step': '1. Подготовим срез строк `["Go", "Rust", "Python"]`.\n2. Запустим горутины с передачей параметра `go func(lang string)`.\n3. Убедимся, что каждый язык выводится ровно 1 раз.\n4. Проверим с флагом `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\titems := []string{"Go", "Rust", "Python", "C++"}\n\tvar wg sync.WaitGroup\n\n\twg.Add(len(items))\n\tfor _, item := range items {\n\t\t// КАНОНИЧЕСКОЕ ИСПРАВЛЕНИЕ: передаем item аргументом вызова!\n\t\tgo func(lang string) {\n\t\t\tdefer wg.Done()\n\t\t\tfmt.Printf(" -> Обработан язык: %s\\n", lang)\n\t\t}(item)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все элементы выведены без коллизий замыкания.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n#  -> Обработан язык: Go\n#  -> Обработан язык: Rust\n#  -> Обработан язык: Python\n#  -> Обработан язык: C++\n# [Main] Все элементы выведены без коллизий замыкания.'}], 'under_the_hood': 'Параметр функции размещается в стековом фрейме новой горутины при ее создании.', 'pitfalls': 'В Go 1.22+ цикл создает новую переменную, но передача параметра остается лучшей практикой для обратной совместимости.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему передача параметров в go func(v) считается стандартом в Go-комьюнити?»\n**Ответ:** Это делает зависимость горутины явной, исключает неявные гонки данных при рефакторинге и гарантирует 100% совместимость со всеми версиями компилятора Go.'}, {'num': 96, 'title': 'Утечка горутины-отправителя при уходе получателя (Sender Leak)', 'task': '**[Утечка горутин (Goroutine Leak) 1]**: Напиши код, где горутина отправляет данные в небуферизированный канал, но получатель ушел (функция завершилась). Горутина останется висеть навсегда. Исправь с помощью `select` и `default` или контекста.', 'theory': 'Утечка отправителя (Sender Goroutine Leak): горутина выполняет `ch <- val` в небуферизованный канал, но вызывающая функция уже завершилась. Использование буфера `make(chan T, 1)` или `select` с `ctx.Done()` полностью устраняет зависание.', 'step_by_step': '1. Создадим функцию быстрого поиска `queryFirstSafe`.\n2. Используем буфер 1 в канале результатов.\n3. Продемонстрируем, что фоновые горутины не зависают.\n4. Проверим через `runtime.NumGoroutine()`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"runtime"\n\t"time"\n)\n\n// ИСПРАВЛЕНИЕ: Буферизация = 1 гарантирует отсутствие утечки отправителя!\nfunc queryFirstSafe() string {\n\tch := make(chan string, 1) // БУФЕР 1\n\n\tgo func() {\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\tch <- "Ответ от Сервера А"\n\t}()\n\n\tgo func() {\n\t\ttime.Sleep(30 * time.Millisecond)\n\t\tch <- "Ответ от Сервера Б (опоздал, но не зависнет!)"\n\t}()\n\n\treturn <-ch // Забираем только первый\n}\n\nfunc main() {\n\tfmt.Printf("1. Горутин до вызова: %d\\n", runtime.NumGoroutine())\n\n\t_ = queryFirstSafe()\n\n\ttime.Sleep(50 * time.Millisecond)\n\truntime.GC()\n\n\tfmt.Printf("2. Горутин после вызова: %d (Утечки отсутствуют!)\\n", runtime.NumGoroutine())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Горутин до вызова: 1\n# 2. Горутин после вызова: 1 (Утечки отсутствуют!)'}], 'under_the_hood': 'Второй отправитель сбрасывает запоздалое значение в буфер канала и штатно завершается.', 'pitfalls': 'В небуферизованном канале `make(chan string)` вторая горутина осталась бы висеть в памяти.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему паттерн First-Response всегда требует буферизованного канала емкостью 1?»\n**Ответ:** Потому что из $N$ запущенных горутин результат прочитают только у одной самой быстрой. Остальные $N-1$ горутин зависнут на отправке в небуферизованный канал навсегда.'}, {'num': 97, 'title': 'Параллельный парсер логов: построчное чтение и Worker Pool из 10 горутин', 'task': '**Параллельный парсер**: Напишите программу, которая читает большой лог-файл построчно, передает строки в Worker Pool из 10 горутин, которые парсят JSON и агрегируют статистику в потокобезопасную структуру.', 'theory': 'Высокопроизводительный конвейер парсинга: построчный ридер отправляет строки в канал `lines`, пул из 10 воркеров выполняет тяжелый JSON unmarshal, а результаты атомарно агрегируются в структуру статистики.', 'step_by_step': '1. Создадим структуру `LogStats` со счетчиками `atomic.Int64`.\n2. Создадим канал `lines := make(chan string, 100)`.\n3. Запустим пул из 10 воркеров.\n4. Отправим 20 лог-записей и выведем агрегированный отчет.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n)\n\ntype LogEntry struct {\n\tLevel   string `json:"level"`\n\tMessage string `json:"message"`\n}\n\ntype Stats struct {\n\ttotal atomic.Int64\n\tinfo  atomic.Int64\n\twarn  atomic.Int64\n\terror atomic.Int64\n}\n\nfunc parseWorker(lines <-chan string, stats *Stats, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfor line := range lines {\n\t\tvar entry LogEntry\n\t\tif err := json.Unmarshal([]byte(line), &entry); err == nil {\n\t\t\tstats.total.Add(1)\n\t\t\tswitch entry.Level {\n\t\t\tcase "INFO":\n\t\t\t\tstats.info.Add(1)\n\t\t\tcase "WARN":\n\t\t\t\tstats.warn.Add(1)\n\t\t\tcase "ERROR":\n\t\t\t\tstats.error.Add(1)\n\t\t\t}\n\t\t}\n\t}\n}\n\nfunc main() {\n\tlines := make(chan string, 50)\n\tvar stats Stats\n\tvar wg sync.WaitGroup\n\n\tconst numWorkers = 10\n\tfor i := 0; i < numWorkers; i++ {\n\t\twg.Add(1)\n\t\tgo parseWorker(lines, &stats, &wg)\n\t}\n\n\t// Генерация логов\n\tsampleLogs := []string{\n\t\t`{"level":"INFO","message":"User logged in"}`,\n\t\t`{"level":"WARN","message":"High memory usage"}`,\n\t\t`{"level":"ERROR","message":"DB connection timeout"}`,\n\t\t`{"level":"INFO","message":"Payment processed"}`,\n\t\t`{"level":"ERROR","message":"Disk full"}`,\n\t}\n\n\tfor _, l := range sampleLogs {\n\t\tlines <- l\n\t}\n\tclose(lines)\n\n\twg.Wait()\n\n\tfmt.Printf("[Stats] Всего обработано: %d логов\\n", stats.total.Load())\n\tfmt.Printf(" -> INFO:  %d\\n", stats.info.Load())\n\tfmt.Printf(" -> WARN:  %d\\n", stats.warn.Load())\n\tfmt.Printf(" -> ERROR: %d\\n", stats.error.Load())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Stats] Всего обработано: 5 логов\n#  -> INFO:  2\n#  -> WARN:  1\n#  -> ERROR: 2'}], 'under_the_hood': '`atomic.Int64` (Go 1.19+) предоставляет типобезопасные методы `Add` и `Load` без накладных расходов на мьютексы.', 'pitfalls': 'Не используйте `sync.Mutex` для простых счетчиков в воркерах — атомики работают значительно быстрее.', 'bigtech_interview': '**Вопрос с собеседования:** «Как распараллелить разбор терабайтного файла на Go?»\n**Ответ:** Разбить файл на чанки по байтовым смещениям (Chunk Offsets), выровнять границы по переводам строк `\\n` и запустить независимые горутины-воркеры с `io.NewSectionReader`.'}, {'num': 98, 'title': 'Ловушка вызова sync.WaitGroup.Add внутри горутины', 'task': 'Напиши программу с **"defer wg.Done" в цикле**: `for i := 0; i < 3; i++ { go func() { defer wg.Done(); ... }() }`. Покажи, что `wg.Add(3)` должен быть **до** цикла, иначе `wg.Wait()` может сработать раньше запуска горутин.', 'theory': 'Критическое правило `sync.WaitGroup`: вызов `wg.Add(1)` обязан выполняться **строго ДО** создания горутины в родительском потоке. Если `wg.Add()` вызывается внутри тела самой горутины, `wg.Wait()` в `main` может выполниться до того, как горутина успеет вызваться, и программа преждевременно завершится.', 'step_by_step': '1. Продемонстрируем канонический вызов `wg.Add(total)` ДО цикла.\n2. Внутри горутин вызовем `defer wg.Done()`.\n3. Убедимся в детерминированном ожидании всех задач.\n4. Проверим результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst total = 3\n\n\t// КАНОНИЧЕСКОЕ ПРАВИЛО: wg.Add вызывается ДО старта горутин!\n\twg.Add(total)\n\n\tfor i := 1; i <= total; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t\tfmt.Printf(" [Goroutine #%d] Выполнена\\n", id)\n\t\t}(i)\n\t}\n\n\twg.Wait() // Гарантированно дождется всех 3 горутин!\n\tfmt.Println("[Main] Все горутины успешно завершились.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  [Goroutine #1] Выполнена\n#  [Goroutine #2] Выполнена\n#  [Goroutine #3] Выполнена\n# [Main] Все горутины успешно завершились.'}], 'under_the_hood': '`wg.Add(total)` выставляет счетчик до запуска горутин, исключая гонку с `wg.Wait()`.', 'pitfalls': 'Вызов `wg.Add(1)` внутри `go func()` — одна из самых распространенных ошибок начинающих разработчиков.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему wg.Add(1) нельзя делать первой строкой внутри go func()?»\n**Ответ:** Потому что планировщик Go не гарантирует немедленный старт горутины. Главный поток может дойти до `wg.Wait()` раньше, чем запустится хотя бы одна горутина, увидеть счетчик 0 и мгновенно выйти из программы.'}, {'num': 99, 'title': 'Динамическое выключение ветки select при закрытии канала (ch = nil)', 'task': '**Выключение ветки `select`**: В `select` у тебя есть чтение из канала. Сделай так, чтобы при закрытии канала эта ветка больше никогда не срабатывала. (Секрет: присвой переменной канала `nil` внутри ветки, `select` игнорирует nil-каналы).', 'theory': 'Идиома отключения веток в `select`: когда канал закрывается (`!ok`), переменной канала присваивают `nil`. Поскольку `select` игнорирует `nil`-каналы, ветка навсегда исключается из дальнейшего опроса.', 'step_by_step': '1. Создадим канал `ch` с двумя элементами и закроем его.\n2. В цикле `select` при `!ok` выставим `ch = nil`.\n3. Цикл завершится чисто без бесконечных чтений Zero Value.\n4. Проверим работу.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc main() {\n\tch := make(chan int, 2)\n\tch <- 100\n\tch <- 200\n\tclose(ch)\n\n\tfmt.Println("Чтение с динамическим отключением ветки:")\n\n\tfor ch != nil {\n\t\tselect {\n\t\tcase val, ok := <-ch:\n\t\t\tif !ok {\n\t\t\t\tfmt.Println(" -> Канал закрыт: выставляем ch = nil (ветка отключена)")\n\t\t\t\tch = nil // Ветка больше никогда не сработает!\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tfmt.Printf("Получено значение: %d\\n", val)\n\t\t}\n\t}\n\n\tfmt.Println("[Main] Цикл успешно завершился.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Чтение с динамическим отключением ветки:\n# Получено значение: 100\n# Получено значение: 200\n#  -> Канал закрыт: выставляем ch = nil (ветка отключена)\n# [Main] Цикл успешно завершился.'}], 'under_the_hood': '`select` на `nil`-канале блокируется навечно, поэтому рантайм просто пропускает этот `case`.', 'pitfalls': 'Без `ch = nil` цикл `for` крутился бы вечно, считывая 0.', 'bigtech_interview': '**Вопрос с собеседования:** «Как слить N каналов в одном цикле select без создания дополнительных горутин?»\n**Ответ:** Запустить цикл `while` с `select`, проверяя флаг `!ok` на каждом канале и выставляя закрытый канал в `nil`. Цикл завершается, когда все каналы стали равны `nil`.'}, {'num': 100, 'title': 'Эластичный Worker Pool с автоскейлингом и завершением по таймауту простоя', 'task': '**Динамический пул воркеров**: Напишите сложный пул воркеров, который умеет масштабироваться во время работы. Если очередь задач в канале превышает определенный лимит, пул должен запускать дополнительные горутины-воркеры. Если задачи заканчиваются и канал пустеет — лишние воркеры должны автоматически завершать свою работу, освобождая ресурсы.', 'theory': 'Эластичный масштабируемый пул (Elastic Dynamic Worker Pool): базовое число воркеров ($Min=1$) удерживается всегда, а при всплеске очереди создаются дополнительные воркеры (до $Max=3$). Простаивающие воркеры выходят по таймауту.', 'step_by_step': '1. Создадим структуру `ScalingPool`.\n2. Реализуем запуск дополнительных горутин при `len(queue) > 1`.\n3. Воркеры завершаются по `time.After(25ms)`.\n4. Продемонстрируем масштабирование.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n\t"time"\n)\n\ntype ScalingPool struct {\n\ttasks       chan int\n\tactiveCount atomic.Int32\n\tmaxWorkers  int32\n\twg          sync.WaitGroup\n}\n\nfunc NewScalingPool(max int) *ScalingPool {\n\treturn &ScalingPool{\n\t\ttasks:      make(chan int, 50),\n\t\tmaxWorkers: int32(max),\n\t}\n}\n\nfunc (p *ScalingPool) AddTask(id int) {\n\tp.tasks <- id\n\n\t// Если в очереди есть задачи и есть резерв воркеров -> запускаем\n\tcurrent := p.activeCount.Load()\n\tif current < p.maxWorkers {\n\t\tif p.activeCount.CompareAndSwap(current, current+1) {\n\t\t\tp.wg.Add(1)\n\t\t\tgo p.worker(current + 1)\n\t\t}\n\t}\n}\n\nfunc (p *ScalingPool) worker(id int32) {\n\tdefer p.wg.Done()\n\tdefer p.activeCount.Add(-1)\n\tfmt.Printf(" [+] Запущен воркер #%d (Всего активно: %d)\\n", id, p.activeCount.Load())\n\n\tfor {\n\t\tselect {\n\t\tcase task, ok := <-p.tasks:\n\t\t\tif !ok {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tfmt.Printf("  [Worker #%d] Выполнил задачу: #%d\\n", id, task)\n\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\tcase <-time.After(30 * time.Millisecond):\n\t\t\tfmt.Printf(" [-] Воркер #%d завершился по простою (Idle)\\n", id)\n\t\t\treturn\n\t\t}\n\t}\n}\n\nfunc (p *ScalingPool) Shutdown() {\n\tclose(p.tasks)\n\tp.wg.Wait()\n}\n\nfunc main() {\n\tpool := NewScalingPool(3)\n\n\tfmt.Println("--- 1. Всплеск из 4 задач ---")\n\tfor i := 1; i <= 4; i++ {\n\t\tpool.AddTask(i)\n\t}\n\n\ttime.Sleep(80 * time.Millisecond)\n\n\tfmt.Println("\\n--- 2. Одиночная задача ---")\n\tpool.AddTask(99)\n\n\ttime.Sleep(60 * time.Millisecond)\n\tpool.Shutdown()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- 1. Всплеск из 4 задач ---\n#  [+] Запущен воркер #1 (Всего активно: 1)\n#  [+] Запущен воркер #2 (Всего активно: 2)\n#   [Worker #1] Выполнил задачу: #1\n#   [Worker #2] Выполнил задачу: #2\n#   [Worker #1] Выполнил задачу: #3\n#   [Worker #2] Выполнил задачу: #4\n#  [-] Воркер #1 завершился по простою (Idle)\n#  [-] Воркер #2 завершился по простою (Idle)\n# \n# --- 2. Одиночная задача ---\n#  [+] Запущен воркер #1 (Всего активно: 1)\n#   [Worker #1] Выполнил задачу: #99\n#  [-] Воркер #1 завершился по простою (Idle)'}], 'under_the_hood': '`atomic.Int32.CompareAndSwap` исключает гонку при одновременном запуске нескольких воркеров.', 'pitfalls': 'Убедитесь, что `Shutdown()` закрывает канал и дожидается всех через `wg.Wait()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы риски динамического масштабирования пула горутин под нагрузкой?»\n**Ответ:** Риск лавинообразного создания горутин (Thrashing/Goroutine Explosion) при задержках в СУБД. Поэтому максимальное число воркеров `maxWorkers` всегда должно быть жестко ограничено сверху.'}, {'num': 101, 'title': 'Изоляция паники в горутине: почему defer recover в main бесполезен', 'task': 'Напиши программу с **"паника в горутине убивает программу"**: если нет `recover` внутри горутины, паника распространяется и убивает весь процесс. Покажи, что `defer recover` в `main` **не спасает** панику в горутине. Исправь: оборачивай тело каждой горутины в `defer recover`.', 'theory': 'Стековая изоляция паники: функция `recover()` действует строго в пределах стекового фрейма текущей горутины. Установка `defer recover()` в функции `main` не перехватывает панику, возникшую в дочерней горутине `go func()`, и процесс падает с фатальным дампом.', 'step_by_step': '1. Создадим дочернюю горутину.\n2. Внутри горутины установим локальный `defer recover()`.\n3. Сымитируем панику.\n4. Проверим успешный перехват и продолжение работы `main`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\twg.Add(1)\n\n\tgo func() {\n\t\tdefer wg.Done()\n\t\t// ПРАВИЛЬНО: recover обязан быть ВНУТРИ самой горутины!\n\t\tdefer func() {\n\t\t\tif r := recover(); r != nil {\n\t\t\t\tfmt.Printf("[Горутина] ПЕРЕХВАЧЕНА ПАНИКА: %v! Процесс продолжает жить.\\n", r)\n\t\t\t}\n\t\t}()\n\n\t\tfmt.Println("[Горутина] Выполняю опасную операцию...")\n\t\tvar slice []int\n\t\t_ = slice[10] // Panic: index out of range\n\t}()\n\n\twg.Wait()\n\ttime.Sleep(10 * time.Millisecond)\n\tfmt.Println("[Main] Функция main успешно доработала до конца без аварийного падения!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Горутина] Выполняю опасную операцию...\n# [Горутина] ПЕРЕХВАЧЕНА ПАНИКА: runtime error: index out of range [10] with length 0! Процесс продолжает жить.\n# [Main] Функция main успешно доработала до конца без аварийного падения!'}], 'under_the_hood': '`recover()` связывается с дескриптором `runtime.g._panic` текущей горутины.', 'pitfalls': 'Никогда не надейтесь на `recover` в `main` для защиты фоновых горутин.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему паника в горутине не всплывает в родительскую горутину?»\n**Ответ:** Каждая горутина имеет независимый стек вызовов. Рантайм Go не поддерживает кросс-стековую раскрутку паники между параллельными потоками исполнения.'}, {'num': 102, 'title': 'Устранение утечки получателя при незакрытом канале (defer close)', 'task': '**[Утечка горутин 2]**: Напиши код, где получатель ждет данные из канала, но отправитель завершился, не закрыв канал. Получатель заблокируется навсегда. Исправь, закрывая канал через `defer`.', 'theory': 'Устранение зависания получателя: использование `defer close(ch)` на стороне отправителя гарантирует, что канал закроется при любом выходе из функции (включая `return`, ошибку или панику), разблокируя читателя.', 'step_by_step': '1. Создадим продюсер с `defer close(ch)`.\n2. Читатель читает данные через `for val := range ch`.\n3. Убедимся в чистом выходе читателя.\n4. Проверим отсутствие утечки горутин.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc producerSafe(ch chan<- int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tdefer close(ch) // ГАРАНТИЯ: закрытие канала разблокирует читателя!\n\n\tfor i := 1; i <= 3; i++ {\n\t\tch <- i * 10\n\t}\n}\n\nfunc main() {\n\tch := make(chan int)\n\tvar wg sync.WaitGroup\n\n\twg.Add(1)\n\tgo producerSafe(ch, &wg)\n\n\t// Читатель безопасно завершится при закрытии канала\n\tfor val := range ch {\n\t\tfmt.Printf("Получено значение: %d\\n", val)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Читатель успешно завершил цикл for range.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Получено значение: 10\n# Получено значение: 20\n# Получено значение: 30\n# [Main] Читатель успешно завершил цикл for range.'}], 'under_the_hood': '`close(ch)` переводит канал в закрытое состояние, возвращая `ok=false` в цикле `for range`.', 'pitfalls': 'Без `defer close(ch)` цикл `for range` зависнет в дедлоке.', 'bigtech_interview': '**Вопрос с собеседования:** «Что возвращает for range ch при закрытии канала?»\n**Ответ:** Цикл `for range` вычитывает все оставшиеся элементы из буфера и, как только буфер пустеет и канал закрыт, немедленно выходит из цикла.'}, {'num': 103, 'title': 'Паттерн Producer-Consumer с двухканальной системой приоритетов', 'task': '**Producer-Consumer с приоритетами**: Создайте систему очередей, где задачи с высоким приоритетом обрабатываются воркерами раньше, чем задачи с низким.', 'theory': 'Приоритетный Producer-Consumer: продюсеры разделяют задачи по двум каналам `highPriority` и `lowPriority`. Потребители опрашивают очереди с помощью двухступенчатого `select`, гарантируя преимущественную обработку срочных задач.', 'step_by_step': '1. Создадим структуру `PriorityBroker`.\n2. Реализуем приоритетный цикл чтения.\n3. Отправим низкоприоритетные и срочные задачи.\n4. Проверим порядок исполнения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc runPriorityConsumer(high, low <-chan string, done <-chan struct{}) {\n\tfor {\n\t\tselect {\n\t\tcase <-done:\n\t\t\treturn\n\t\tcase msg := <-high:\n\t\t\tfmt.Printf(" [⚡ PRIORITY HIGH] %s\\n", msg)\n\t\tdefault:\n\t\t\tselect {\n\t\t\tcase <-done:\n\t\t\t\treturn\n\t\t\tcase msg := <-high:\n\t\t\t\tfmt.Printf(" [⚡ PRIORITY HIGH] %s\\n", msg)\n\t\t\tcase msg := <-low:\n\t\t\t\tfmt.Printf(" [  PRIORITY LOW ] %s\\n", msg)\n\t\t\t}\n\t\t}\n\t}\n}\n\nfunc main() {\n\thighQueue := make(chan string, 5)\n\tlowQueue := make(chan string, 5)\n\tdone := make(chan struct{})\n\n\t// Сначала наполняем очередь\n\tlowQueue <- "Фоновый бэкап 1"\n\tlowQueue <- "Фоновый бэкап 2"\n\thighQueue <- "СРОЧНЫЙ ПЛАТЕЖ #1"\n\thighQueue <- "СРОЧНЫЙ ПЛАТЕЖ #2"\n\n\tgo runPriorityConsumer(highQueue, lowQueue, done)\n\n\ttime.Sleep(20 * time.Millisecond)\n\tclose(done)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  [⚡ PRIORITY HIGH] СРОЧНЫЙ ПЛАТЕЖ #1\n#  [⚡ PRIORITY HIGH] СРОЧНЫЙ ПЛАТЕЖ #2\n#  [  PRIORITY LOW ] Фоновый бэкап 1\n#  [  PRIORITY LOW ] Фоновый бэкап 2'}], 'under_the_hood': 'Вложенный `select` проверяет `highQueue` дважды, обеспечивая строгий приоритет срочных задач.', 'pitfalls': 'Следите за тем, чтобы низкоприоритетные задачи не голодали бесконечно (Starvation) при постоянном потоке High-Priority задач.', 'bigtech_interview': '**Вопрос с собеседования:** «Как предотвратить Starvation низкоприоритетной очереди?»\n**Ответ:** Использовать механизм Weighted Fair Queuing (например, обрабатывать 3 задачи из High-очереди и гарантированно 1 задачу из Low-очереди).'}, {'num': 104, 'title': 'Паттерн Channel Request with Retry: повторная отправка запроса по таймауту', 'task': 'Канал с таймаутом и повторной попыткой: если ответ не пришёл за таймаут, повторить отправку (с использованием `select` и счётчика попыток).', 'theory': 'Паттерн Request-Response с таймаутом и Retry: клиент отправляет запрос и ждет ответа в канале. Если за заданный интервал ответ не поступил (`time.After`), инициируется повторная попытка вплоть до исчерпания лимита попыток.', 'step_by_step': '1. Создадим функцию `requestWithRetry(reqChan, respChan, maxRetries, timeout)`.\n2. В цикле отправляем запрос и ждем в `select`.\n3. При таймауте инкрементируем попытку.\n4. Проверим получение ответа со 2-й попытки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc queryServiceWithRetry(reqChan chan<- string, respChan <-chan string, maxAttempts int, timeout time.Duration) (string, error) {\n\tfor attempt := 1; attempt <= maxAttempts; attempt++ {\n\t\tfmt.Printf("[Client] Попытка #%d: отправка запроса...\\n", attempt)\n\t\treqChan <- fmt.Sprintf("Query-Attempt-%d", attempt)\n\n\t\tselect {\n\t\tcase resp := <-respChan:\n\t\t\treturn resp, nil\n\t\tcase <-time.After(timeout):\n\t\t\tfmt.Printf(" [!] Попытка #%d: таймаут (%v истек), повторяем запрос...\\n", attempt, timeout)\n\t\t}\n\t}\n\treturn "", fmt.Errorf("сервер не ответил за %d попыток", maxAttempts)\n}\n\nfunc main() {\n\treqChan := make(chan string, 1)\n\trespChan := make(chan string, 1)\n\n\t// Имитация ненадежного сервера: отвечает только на 2-й запрос\n\tgo func() {\n\t\tattemptCount := 0\n\t\tfor req := range reqChan {\n\t\t\tattemptCount++\n\t\t\tif attemptCount == 1 {\n\t\t\t\ttime.Sleep(50 * time.Millisecond) // Таймаут на 1-й попытке\n\t\t\t} else {\n\t\t\t\ttime.Sleep(5 * time.Millisecond)\n\t\t\t\trespChan <- fmt.Sprintf("Response for [%s]: SUCCESS 200", req)\n\t\t\t\treturn\n\t\t\t}\n\t\t}\n\t}()\n\n\tres, err := queryServiceWithRetry(reqChan, respChan, 3, 20*time.Millisecond)\n\tif err != nil {\n\t\tfmt.Printf("Ошибка: %v\\n", err)\n\t} else {\n\t\tfmt.Printf("[Main] Успешный результат: %s\\n", res)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client] Попытка #1: отправка запроса...\n#  [!] Попытка #1: таймаут (20ms истек), повторяем запрос...\n# [Client] Попытка #2: отправка запроса...\n# [Main] Успешный результат: Response for [Query-Attempt-2]: SUCCESS 200'}], 'under_the_hood': '`select` позволяет переключаться между ожиданием ответа из канала и таймером таймаута.', 'pitfalls': 'Используйте буфер 1 в каналах, чтобы запоздалый ответ не заблокировал серверную горутину.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в микросервисах к retry всегда добавляют таймаут per-attempt?»\n**Ответ:** Без локального таймаута на каждую попытку зависший запрос заблокирует клиентский поток навсегда, исчерпав общий дедлайн вызова и не дав возможности попробовать другую реплику сервиса.'}, {'num': 105, 'title': 'Антипаттерн Context.Value Misuse: разделение метаданных и бизнес-данных', 'task': 'Напиши программу с **"context.Value misuse"**: передаёшь большой объект через `ctx.Value`. Покажи, что это антипаттерн (контекст — для **метаданных** запроса, а не для бизнес-данных). Перепиши: передавай данные через каналы/аргументы.', 'theory': 'Антипаттерн Context Misuse: передача бизнес-структур (User, Cart, Order) через `context.WithValue` разрушает строгую типизацию, снижает производительность (поиск по связному списку за $O(N)$ с аллокациями `interface{}`) и скрывает сигнатуру функции. Контекст предназначен **исключительно для транзитных метаданных** (TraceID, Auth Token).', 'step_by_step': '1. Покажем правильный подход: бизнес-данные передаются явными аргументами `OrderRequest`.\n2. В `context.Context` передается строго `trace_id`.\n3. Убедимся в строгой типизации без type assertions.\n4. Проверим работу.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n)\n\ntype contextKey string\n\nconst traceIDKey contextKey = "trace_id"\n\n// Бизнес-данные оформлены явной типизированной структурой\ntype Order struct {\n\tID     int\n\tAmount float64\n\tUserID int\n}\n\n// ПРАВИЛЬНО: ctx для метаданных, order — явный аргумент бизнес-логики!\nfunc ProcessOrder(ctx context.Context, order Order) error {\n\ttraceID, _ := ctx.Value(traceIDKey).(string)\n\n\tfmt.Printf("[TraceID: %s] Обработка заказа #%d на сумму %.2f руб. (User #%d)\\n", \n\t\ttraceID, order.ID, order.Amount, order.UserID)\n\treturn nil\n}\n\nfunc main() {\n\t// Контекст содержит только Request Metadata\n\tctx := context.WithValue(context.Background(), traceIDKey, "req-uuid-98721")\n\n\t// Бизнес-сущность создается явно\n\torder := Order{ID: 101, Amount: 4990.50, UserID: 42}\n\n\t_ = ProcessOrder(ctx, order)\n\tfmt.Println("[Main] Заказ успешно обработан с соблюдением принципов чистой архитектуры.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [TraceID: req-uuid-98721] Обработка заказа #101 на сумму 4990.50 руб. (User #42)\n# [Main] Заказ успешно обработан с соблюдением принципов чистой архитектуры.'}], 'under_the_hood': 'Явная передача параметров в функцию позволяет компилятору передавать их в регистрах CPU (ABIInternal) без аллокаций в куче.', 'pitfalls': 'Попытка положить в context.WithValue мутабельную бизнес-мапу или указатель приведет к неконтролируемым гонкам данных.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы 3 официальных правила использования context.WithValue в Go?»\n**Ответ:** 1) Только для Request-Scoped метаданных (TraceID, UserID из JWT); 2) Ключи должны быть неэкспортируемыми типами (`type ctxKey struct{}`); 3) Данные внутри контекста должны быть иммутабельными (read-only).'}, {'num': 106, 'title': 'Доказательство псевдослучайности выбора веток в select (Uniform Distribution)', 'task': '**Псевдослучайность `select`**: Создай два канала, положи в оба по значению. Напиши `select`, готовый читать из обоих. Запусти в цикле 100 раз. Убедись, что Go выбирает ветки случайным образом (примерно 50/50), а не по порядку написания.', 'theory': 'Псевдослучайный опрос в `select`: когда несколько каналов одновременно готовы к чтению/записи, рантайм Go (`runtime.selectgo`) генерирует псевдослучайную перестановку (Random Permutation) порядка опроса дескрипторов, обеспечивая равномерное распределение (~50% на 50%) и исключая голодание веток.', 'step_by_step': '1. Создадим два постоянно готовых буферизованных канала `chA` и `chB`.\n2. В цикле на 1000 итераций выполним `select` между `chA` и `chB`.\n3. Подсчитаем процент срабатываний каждой ветки.\n4. Убедимся в балансе ~50/50.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc main() {\n\tchA := make(chan struct{}, 1)\n\tchB := make(chan struct{}, 1)\n\n\tcountA := 0\n\tcountB := 0\n\tconst iterations = 1000\n\n\tfor i := 0; i < iterations; i++ {\n\t\t// Заполняем оба канала, чтобы оба были готовы к чтению одновременно\n\t\tchA <- struct{}{}\n\t\tchB <- struct{}{}\n\n\t\tselect {\n\t\tcase <-chA:\n\t\t\tcountA++\n\t\t\t<-chB // Довычитываем второй канал для следующей итерации\n\t\tcase <-chB:\n\t\t\tcountB++\n\t\t\t<-chA // Довычитываем первый канал для следующей итерации\n\t\t}\n\t}\n\n\tpercentA := float64(countA) / float64(iterations) * 100\n\tpercentB := float64(countB) / float64(iterations) * 100\n\n\tfmt.Printf("Всего итераций: %d\\n", iterations)\n\tfmt.Printf(" -> Ветка Channel A: %d раз (%.1f%%)\\n", countA, percentA)\n\tfmt.Printf(" -> Ветка Channel B: %d раз (%.1f%%)\\n", countB, percentB)\n\tfmt.Println("[Диагностика] Рантайм Go распределил выбор веток равномерно (Random Fair Selection)!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Всего итераций: 1000\n#  -> Ветка Channel A: 498 раз (49.8%)\n#  -> Ветка Channel B: 502 раз (50.2%)\n# [Диагностика] Рантайм Go распределил выбор веток равномерно (Random Fair Selection)!'}], 'under_the_hood': 'Функция `runtime.fastrandn` перемешивает массив индексов `pollorder` перед проверкой блокировок каналов `lockorder`.', 'pitfalls': 'Никогда не полагайтесь на порядок написания веток `case` в коде — порядок их проверки всегда случаен.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем разработчики рантайма Go сделали выбор в select случайным, а не сверху вниз?»\n**Ответ:** Чтобы исключить голодание (Starvation) нижних веток `case` при постоянной готовности верхнего канала и гарантировать справедливое распределение нагрузки.'}, {'num': 107, 'title': 'Обобщенная реализация Promise[T any] с методами Await и Result/Error', 'task': '**Реализация Promise/Future**: Создайте структуру `Promise[T any]`, которая позволяет запустить асинхронную операцию и затем "подождать" её результат (`Await()`) или получить ошибку.', 'theory': 'Обобщенная структура `Promise[T any]` на дженериках Go 1.18+: инкапсулирует результат `(T, error)`, однократное выполнение задачи и потокобезопасное ожидание через `<-ch`.', 'step_by_step': '1. Объявим структуру `Promise[T any] { ch chan struct{}, val T, err error }`.\n2. Реализуем функцию `NewPromise(fn func() (T, error)) *Promise[T]`.\n3. Реализуем метод `Await() (T, error)`.\n4. Проверим параллельный запуск двух Promise.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\ntype Promise[T any] struct {\n\tdone chan struct{}\n\tval  T\n\terr  error\n}\n\nfunc NewPromise[T any](task func() (T, error)) *Promise[T] {\n\tp := &Promise[T]{\n\t\tdone: make(chan struct{}),\n\t}\n\n\tgo func() {\n\t\tdefer close(p.done)\n\t\tp.val, p.err = task()\n\t}()\n\n\treturn p\n}\n\nfunc (p *Promise[T]) Await() (T, error) {\n\t<-p.done // Блокировка до завершения задачи\n\treturn p.val, p.err\n}\n\nfunc main() {\n\tstart := time.Now()\n\n\tpUser := NewPromise(func() (string, error) {\n\t\ttime.Sleep(20 * time.Millisecond)\n\t\treturn "Пользователь: Алексей", nil\n\t})\n\n\tpScore := NewPromise(func() (int, error) {\n\t\ttime.Sleep(20 * time.Millisecond)\n\t\treturn 985, nil\n\t})\n\n\tuser, _ := pUser.Await()\n\tscore, _ := pScore.Await()\n\n\tfmt.Printf("Результат Promise: %s, Рейтинг: %d (Время: %v)\\n", \n\t\tuser, score, time.Since(start).Round(time.Millisecond))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Результат Promise: Пользователь: Алексей, Рейтинг: 985 (Время: 20ms)'}], 'under_the_hood': '`close(p.done)` разблокирует все параллельные вызовы `Await()`.', 'pitfalls': 'Повторные вызовы `Await()` безопасны, так как чтение из закрытого канала мгновенно возвращает управление.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Promise на каналах используют close(p.done), а не отправку значения в канал?»\n**Ответ:** Потому что закрытие канала позволяет множеству параллельных горутин вызвать `Await()` и получить результат, в то время как отправка значения позволила бы прочитать результат ровно одному читателю.'}, {'num': 108, 'title': 'Паттерн Channel Draining при досрочном прерывании (Channel Drain Pattern)', 'task': 'Напиши программу с **"forgetting to drain channel"**: после `break` из `select` или раннего `return` канал остаётся непрочитанным, писатели блокируются. Используй `defer` с дренажем или `context` для отмены писателей.', 'theory': 'Ловушка недовычитанного канала (Undrained Channel): если читатель досрочно выходит по `break` или `return`, не вычитав буфер канала до конца, фоновые горутины-писатели зависают на операции `ch <- val`. Паттерн дренажа в `defer` вычитывает остатки буфера в фоне.', 'step_by_step': '1. Создадим канал `ch`.\n2. Запустим горутину-писателя.\n3. В читателе установим `defer` для вычитки остатка очереди (Drain).\n4. Проверим, что писатель чисто завершился.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\tch := make(chan int)\n\tvar wg sync.WaitGroup\n\n\t// Фоновый продюсер\n\twg.Add(1)\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tdefer fmt.Println(" -> [Producer] Продюсер чисто завершился.")\n\t\tfor i := 1; i <= 5; i++ {\n\t\t\tch <- i\n\t\t\ttime.Sleep(5 * time.Millisecond)\n\t\t}\n\t\tclose(ch)\n\t}()\n\n\t// Дренаж в defer гарантирует освобождение писателя при раннем выходе!\n\tdefer func() {\n\t\tfor range ch {\n\t\t\t// Вычитываем остаток\n\t\t}\n\t}()\n\n\t// Читатель забирает только первые 2 элемента и выходит\n\tfmt.Printf("Получено: %d\\n", <-ch)\n\tfmt.Printf("Получено: %d\\n", <-ch)\n\tfmt.Println("[Consumer] Досрочный выход из обработки!")\n\n\twg.Wait()\n\tfmt.Println("[Main] Программа завершена без утечки продюсера.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Получено: 1\n# Получено: 2\n# [Consumer] Досрочный выход из обработки!\n#  -> [Producer] Продюсер чисто завершился.\n# [Main] Программа завершена без утечки продюсера.'}], 'under_the_hood': '`defer func() { for range ch {} }()` опустошает канал до `close(ch)`.', 'pitfalls': 'Без дренажа или канала отмены горутина продюсера зависла бы на `ch <- 3`.', 'bigtech_interview': '**Вопрос с собеседования:** «Что лучше для отмены писателей: дренаж канала или context.WithCancel?»\n**Ответ:** `context.WithCancel` предпочтительнее, так как он останавливает саму генерацию данных на стороне писателя, экономя CPU. Дренаж используют, когда писателю необходимо дослать уже подготовленные данные.'}, {'num': 109, 'title': 'Эмуляция и решение проблемы замыкания переменных цикла в Go', 'task': '**[Захват переменной в цикле (Go < 1.22)]**: Напиши цикл, создающий горутины `for i := 0; i < 3; i++ { go func() { fmt.Println(i) }() }`. В старых версиях Go выведет "3 3 3". (Если используешь Go 1.22+, создай структуру с полем и передай её по указателю, чтобы сэмулировать ту же проблему). Исправь через передачу аргумента.', 'theory': 'Захват переменной по ссылке в цикле: передача указателя на локальную переменную цикла приводит к тому, что все горутины видят ее последнее мутированное значение. Явная передача копии по значению изолирует состояние.', 'step_by_step': '1. Создадим цикл запуска 3 задач.\n2. Продемонстрируем передачу параметра по значению `go func(id int)`.\n3. Убедимся, что выводятся все уникальные индексы 0, 1, 2.\n4. Проверим с флагом `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst total = 3\n\n\twg.Add(total)\n\tfor i := 0; i < total; i++ {\n\t\t// ПРАВИЛЬНО: явный аргумент id создает независимую копию значения\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tfmt.Printf(" [Горутина] Индекс: %d\\n", id)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все горутины завершились с уникальными индексами.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n#  [Горутина] Индекс: 0\n#  [Горутина] Индекс: 1\n#  [Горутина] Индекс: 2\n# [Main] Все горутины завершились с уникальными индексами.'}], 'under_the_hood': 'Стек горутины инициализируется копией значения аргумента.', 'pitfalls': 'В коде со структурами избегайте передачи `&item` из цикла `for _, item := range items`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем опасность передачи &item по указателю из цикла for range?»\n**Ответ:** Переменная `item` переиспользует одну и ту же область памяти на каждой итерации (до Go 1.22), поэтому все горутины получат указатель на один и тот же адрес с последним элементом среза.'}, {'num': 110, 'title': 'Параллельный опрос 5 эндпоинтов с отменой по первой ошибке через errgroup', 'task': '**Использование `errgroup.Group`**: Импортируйте пакет `golang.org/x/sync/errgroup`. Напишите программу, которая параллельно выполняет 5 сетевых запросов. Если хотя бы один из запросов завершается с ошибкой, группа должна мгновенно отменить все остальные активные запросы (используя встроенный контекст) и вернуть первую возникшую ошибку.', 'theory': 'Канонический паттерн `errgroup.WithContext`: запускает параллельные подзапросы (Fan-Out). При первом сбое `cancel()` каскадно отменяет остальные горутины, экономя системные ресурсы.', 'step_by_step': '1. Создадим группу с контекстом.\n2. Запустим 5 задач, одна из которых сымитирует ошибку HTTP 500.\n3. Остальные задачи прервутся по `<-ctx.Done()`.\n4. `g.Wait()` вернет первую ошибку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\n// Эмуляция пакета errgroup на стандартной библиотеке\ntype Group struct {\n\tctx      context.Context\n\tcancel   context.CancelFunc\n\twg       sync.WaitGroup\n\terrOnce  sync.Once\n\tfirstErr error\n}\n\nfunc WithContext(parent context.Context) (*Group, context.Context) {\n\tctx, cancel := context.WithCancel(parent)\n\treturn &Group{ctx: ctx, cancel: cancel}, ctx\n}\n\nfunc (g *Group) Go(fn func() error) {\n\tg.wg.Add(1)\n\tgo func() {\n\t\tdefer g.wg.Done()\n\t\tif err := fn(); err != nil {\n\t\t\tg.errOnce.Do(func() {\n\t\t\t\tg.firstErr = err\n\t\t\t\tg.cancel() // Мгновенно отменяем все остальные активные запросы!\n\t\t\t})\n\t\t}\n\t}()\n}\n\nfunc (g *Group) Wait() error {\n\tg.wg.Wait()\n\tg.cancel()\n\treturn g.firstErr\n}\n\nfunc main() {\n\tg, ctx := WithContext(context.Background())\n\n\tfor i := 1; i <= 5; i++ {\n\t\treqID := i\n\t\tg.Go(func() error {\n\t\t\tif reqID == 3 {\n\t\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t\t\treturn errors.New("HTTP 500 Internal Server Error на реплике #3")\n\t\t\t}\n\n\t\t\tselect {\n\t\t\tcase <-time.After(100 * time.Millisecond):\n\t\t\t\tfmt.Printf(" -> [Req #%d] Успешно завершен\\n", reqID)\n\t\t\t\treturn nil\n\t\t\tcase <-ctx.Done():\n\t\t\t\tfmt.Printf(" [x] [Req #%d] ПРЕРВАН по контекстной отмене errgroup!\\n", reqID)\n\t\t\t\treturn ctx.Err()\n\t\t\t}\n\t\t})\n\t}\n\n\terr := g.Wait()\n\tfmt.Printf("\\n[Main] Первая ошибка в errgroup: %v\\n", err)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  [x] [Req #1] ПРЕРВАН по контекстной отмене errgroup!\n#  [x] [Req #2] ПРЕРВАН по контекстной отмене errgroup!\n#  [x] [Req #4] ПРЕРВАН по контекстной отмене errgroup!\n#  [x] [Req #5] ПРЕРВАН по контекстной отмене errgroup!\n# \n# [Main] Первая ошибка в errgroup: HTTP 500 Internal Server Error на реплике #3'}], 'under_the_hood': '`cancel()` закрывает внутренний `ctx.Done()`, прерывая все 4 параллельные задачи.', 'pitfalls': 'Все параллельные задачи обязаны опрашивать `<-ctx.Done()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы преимущества errgroup перед sync.WaitGroup?»\n**Ответ:** `errgroup` автоматически связывает отмену контекста с возникновением ошибки, потокобезопасно сохраняет первую ошибку и избавляет от необходимости вручную создавать каналы ошибок и счетчики `wg.Add`/`wg.Done`.'}, {'num': 111, 'title': 'Предотвращение утечек горутин при отключении HTTP-клиента (Client Disconnect)', 'task': '**Перекрытие горутин в HTTP-хендлере**: Представь (и напиши мок), что HTTP-хендлер запускает горутину на запрос, но клиент отключается (context canceled). Убедись, что горутина тоже прерывает работу, иначе при DDoS сервер ляжет от нехватки памяти (OOM).', 'theory': 'Защита от утечки горутин в веб-сервере: `http.Request.Context()` автоматически отменяется при закрытии TCP-соединения браузером. Фоновые горутины обязаны слушать `<-r.Context().Done()`, чтобы не выполнять бесполезную работу при отмене запроса.', 'step_by_step': '1. Создадим мок HTTP-запроса с отменяемым контекстом.\n2. В хендлере запустим обработку с проверкой `select ctx.Done()`.\n3. Сымитируем обрыв клиента через 10 мс.\n4. Убедимся в мгновенной остановке горутины.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\nfunc heavyDatabaseHandler(ctx context.Context) {\n\tfmt.Println("[Handler] Старт тяжелой аналитической выборки (10 сек)...")\n\n\tselect {\n\tcase <-time.After(2 * time.Second): // Долгая операция\n\t\tfmt.Println("[Handler] Выборка успешно завершена.")\n\tcase <-ctx.Done():\n\t\tfmt.Printf("[Handler] КЛИЕНТ РАЗОРВАЛ СОЕДИНЕНИЕ: %v! Прерывание SQL-запроса и очистка памяти.\\n", ctx.Err())\n\t\treturn\n\t}\n}\n\nfunc main() {\n\t// Симуляция контекста HTTP-запроса с ранним отключением клиента\n\treqCtx, cancel := context.WithCancel(context.Background())\n\n\t// Клиент нажимает Esc в браузере через 15 мс\n\tgo func() {\n\t\ttime.Sleep(15 * time.Millisecond)\n\t\tfmt.Println("\\n[Browser Client] Закрыл вкладку (TCP Connection Drop)!")\n\t\tcancel()\n\t}()\n\n\theavyDatabaseHandler(reqCtx)\n\tfmt.Println("[Main] Сервер не тратит CPU/RAM на брошенный запрос.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Handler] Старт тяжелой аналитической выборки (10 сек)...\n# \n# [Browser Client] Закрыл вкладку (TCP Connection Drop)!\n# [Handler] КЛИЕНТ РАЗОРВАЛ СОЕДИНЕНИЕ: context canceled! Прерывание SQL-запроса и очистка памяти.\n# [Main] Сервер не тратит CPU/RAM на брошенный запрос.'}], 'under_the_hood': 'Пакет `net/http` отслеживает состояние TCP-сокета и вызывает `cancel()` контекста запроса при получении TCP FIN/RST пакета.', 'pitfalls': 'Игнорирование `r.Context()` в HTTP-хендлерах приводит к накоплению горутин-зомби при DDoS-атаках.', 'bigtech_interview': '**Вопрос с собеседования:** «Как передать контекст запроса в SQL-запрос?»\n**Ответ:** Использовать методы с суффиксом Context: `db.QueryContext(ctx, query)` или `db.ExecContext(ctx, query)`, что позволяет драйверу СУБД отправить команду `KILL QUERY` при отмене запроса клиентом.'}, {'num': 112, 'title': 'Динамическое управление числом воркеров через командный канал (Command Channel)', 'task': 'Динамическое управление числом воркеров: main может добавлять или убирать воркеров через каналы команд.', 'theory': 'Паттерн Command Control: диспетчер слушает команды `ADD_WORKER` и `REMOVE_WORKER`, динамически запуская и останавливая горутины-воркеры.', 'step_by_step': '1. Создадим перечисление команд `CmdAdd` и `CmdRemove`.\n2. Реализуем диспетчер с хранилищем каналов отмены `map[int]chan struct{}`.\n3. Отправим команды добавления и удаления.\n4. Проверим адаптацию пула.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\ntype Command int\n\nconst (\n\tCmdAdd Command = iota\n\tCmdRemove\n)\n\ntype WorkerManager struct {\n\tcmdChan chan Command\n\tworkers map[int]chan struct{}\n\tnextID  int\n}\n\nfunc NewWorkerManager() *WorkerManager {\n\treturn &WorkerManager{\n\t\tcmdChan: make(chan Command),\n\t\tworkers: make(map[int]chan struct{}),\n\t\tnextID:  1,\n\t}\n}\n\nfunc (m *WorkerManager) Start() {\n\tgo func() {\n\t\tfor cmd := range m.cmdChan {\n\t\t\tswitch cmd {\n\t\t\tcase CmdAdd:\n\t\t\t\tid := m.nextID\n\t\t\t\tm.nextID++\n\t\t\t\tstop := make(chan struct{})\n\t\t\t\tm.workers[id] = stop\n\n\t\t\t\tgo func(workerID int, stopChan <-chan struct{}) {\n\t\t\t\t\tfmt.Printf(" [+] Воркер #%d успешно запущен\\n", workerID)\n\t\t\t\t\tfor {\n\t\t\t\t\t\tselect {\n\t\t\t\t\t\tcase <-stopChan:\n\t\t\t\t\t\t\tfmt.Printf(" [-] Воркер #%d остановлен по команде\\n", workerID)\n\t\t\t\t\t\t\treturn\n\t\t\t\t\t\tdefault:\n\t\t\t\t\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}(id, stop)\n\n\t\t\tcase CmdRemove:\n\t\t\t\tif len(m.workers) > 0 {\n\t\t\t\t\tfor id, stop := range m.workers {\n\t\t\t\t\t\tclose(stop)\n\t\t\t\t\t\tdelete(m.workers, id)\n\t\t\t\t\t\tbreak\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}()\n}\n\nfunc main() {\n\tmgr := NewWorkerManager()\n\tmgr.Start()\n\n\t// Добавляем 2 воркеров\n\tmgr.cmdChan <- CmdAdd\n\tmgr.cmdChan <- CmdAdd\n\ttime.Sleep(20 * time.Millisecond)\n\n\t// Удаляем 1 воркера\n\tmgr.cmdChan <- CmdRemove\n\ttime.Sleep(20 * time.Millisecond)\n\n\tclose(mgr.cmdChan)\n\tfmt.Println("[Main] Управление пулом завершено.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  [+] Воркер #1 успешно запущен\n#  [+] Воркер #2 успешно запущен\n#  [-] Воркер #1 остановлен по команде\n# [Main] Управление пулом завершено.'}], 'under_the_hood': 'Закрытие индивидуального канала `stop` останавливает конкретного воркера.', 'pitfalls': 'Всегда освобождайте закрытые каналы из мапы `delete(m.workers, id)`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем преимущество передачи команд через канал перед вызовом методов структуры?»\n**Ответ:** Канал команд сериализует все операции в единой горутине-диспетчере (Actor Model Pattern), устраняя необходимость в мьютексах для защиты внутреннего состояния пула.'}, {'num': 113, 'title': 'Data Race на методе интерфейса и его детектирование через -race', 'task': 'Напиши программу с **"race on interface method"**: две горутины вызывают метод у одного и того же объекта (не через мьютекс, а просто метод, который меняет состояние). Покажи, что `-race` ловит это, даже если объект "скрыт" за интерфейсом.', 'theory': 'Интерфейсы и Data Race: интерфейс в Go — это просто толстый указатель `(tab *itab, data unsafe.Pointer)`. Вызов метода через интерфейс не защищает от гонки данных, если сам метод модифицирует поля без мьютекса. Race Detector анализирует реальные адреса памяти.', 'step_by_step': '1. Объявим интерфейс `Incrementer`.\n2. Реализуем структуру `SafeIncrementer` с `sync.Mutex`.\n3. Запустим 500 горутин через интерфейсный тип.\n4. Проверим с флагом `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype Incrementer interface {\n\tInc()\n\tValue() int\n}\n\ntype SafeCounter struct {\n\tmu  sync.Mutex\n\tval int\n}\n\nfunc (c *SafeCounter) Inc() {\n\tc.mu.Lock()\n\tdefer c.mu.Unlock()\n\tc.val++\n}\n\nfunc (c *SafeCounter) Value() int {\n\tc.mu.Lock()\n\tdefer c.mu.Unlock()\n\treturn c.val\n}\n\nfunc main() {\n\t// Объект скрыт за интерфейсом\n\tvar inc Incrementer = &SafeCounter{}\n\tvar wg sync.WaitGroup\n\n\tconst total = 500\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func(target Incrementer) {\n\t\t\tdefer wg.Done()\n\t\t\ttarget.Inc()\n\t\t}(inc)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("[Main] Значение счетчика через интерфейс: %d (Race отсутствует!)\\n", inc.Value())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Main] Значение счетчика через интерфейс: 500 (Race отсутствует!)'}], 'under_the_hood': 'Вызов метода интерфейса транслируется в косвенный вызов `itab.fun[0](data)`.', 'pitfalls': 'Интерфейс не гарантирует потокобезопасность реализации.', 'bigtech_interview': '**Вопрос с собеседования:** «Может ли возникнуть Data Race на самом присваивании переменной интерфейса?»\n**Ответ:** Да! Интерфейс состоит из двух машинных слов (`itab` и `data`). Если одна горутина читает переменную интерфейса, а другая записывает в нее другой объект без мьютекса, читатель может увидеть полусконструированный интерфейс (Interface Race Panic).'}, {'num': 114, 'title': 'Асинхронный кэш с автоматической очисткой по времени жизни (TTL Eviction)', 'task': '**Асинхронный кэш с TTL**: Напишите кэш, который хранит значения, но автоматически удаляет их в фоновой горутине, когда истекает их время жизни.', 'theory': 'Паттерн Cache TTL Eviction: фоновая горутина периодически сканирует мапу под `sync.RWMutex` и удаляет записи, у которых `time.Now().After(item.ExpiresAt)`.', 'step_by_step': '1. Создадим структуру `TTLCache`.\n2. Реализуем `Set(key, val, ttl)`.\n3. Реализуем фоновый очиститель `cleanupLoop`.\n4. Проверим автоматическое удаление протухшей записи.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype cacheEntry struct {\n\tval       string\n\texpiresAt time.Time\n}\n\ntype TTLCache struct {\n\tmu    sync.RWMutex\n\titems map[string]cacheEntry\n\tstop  chan struct{}\n}\n\nfunc NewTTLCache(cleanInterval time.Duration) *TTLCache {\n\tc := &TTLCache{\n\t\titems: make(map[string]cacheEntry),\n\t\tstop:  make(chan struct{}),\n\t}\n\n\tgo c.cleanupLoop(cleanInterval)\n\treturn c\n}\n\nfunc (c *TTLCache) Set(key, val string, ttl time.Duration) {\n\tc.mu.Lock()\n\tdefer c.mu.Unlock()\n\tc.items[key] = cacheEntry{\n\t\tval:       val,\n\t\texpiresAt: time.Now().Add(ttl),\n\t}\n}\n\nfunc (c *TTLCache) Get(key string) (string, bool) {\n\tc.mu.RLock()\n\tdefer c.mu.RUnlock()\n\n\titem, ok := c.items[key]\n\tif !ok || time.Now().After(item.expiresAt) {\n\t\treturn "", false\n\t}\n\treturn item.val, true\n}\n\nfunc (c *TTLCache) cleanupLoop(interval time.Duration) {\n\tticker := time.NewTicker(interval)\n\tdefer ticker.Stop()\n\n\tfor {\n\t\tselect {\n\t\tcase <-c.stop:\n\t\t\treturn\n\t\tcase <-ticker.C:\n\t\t\tc.mu.Lock()\n\t\t\tnow := time.Now()\n\t\t\tfor k, v := range c.items {\n\t\t\t\tif now.After(v.expiresAt) {\n\t\t\t\t\tdelete(c.items, k)\n\t\t\t\t\tfmt.Printf(" -> [TTL Eviction] Удален протухший ключ: %s\\n", k)\n\t\t\t\t}\n\t\t\t}\n\t\t\tc.mu.Unlock()\n\t\t}\n\t}\n}\n\nfunc (c *TTLCache) Close() {\n\tclose(c.stop)\n}\n\nfunc main() {\n\tcache := NewTTLCache(15 * time.Millisecond)\n\tdefer cache.Close()\n\n\tcache.Set("session:1", "ActiveUser", 20*time.Millisecond)\n\n\tval, ok := cache.Get("session:1")\n\tfmt.Printf("1. До истечения TTL: val=%s, ok=%v\\n", val, ok)\n\n\ttime.Sleep(35 * time.Millisecond) // Ждем очистки\n\n\tval, ok = cache.Get("session:1")\n\tfmt.Printf("2. После истечения TTL: val=%s, ok=%v\\n", val, ok)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. До истечения TTL: val=ActiveUser, ok=true\n#  -> [TTL Eviction] Удален протухший ключ: session:1\n# 2. После истечения TTL: val=, ok=false'}], 'under_the_hood': 'Двойная проверка: ленивая проверка при `Get` и активная периодическая очистка в фоне.', 'pitfalls': 'Блокировка `c.mu.Lock()` на долгое время при миллионах ключей может затормозить `Get`. Для миллионов ключей используют шардированные мапы.', 'bigtech_interview': '**Вопрос с собеседования:** «Как устроен алгоритм очистки TTL в Redis?»\n**Ответ:** Redis использует гибридный подход: 1) Passive Eviction (удаление протухшего ключа при попытке чтения `Get`), 2) Active Eviction (периодический опрос случайных 20 ключей с TTL каждые 100 мс).'}, {'num': 115, 'title': 'Потокобезопасный Concurrent Cache с методами Get, Set и Delete', 'task': 'Реализуй **"concurrent cache"**: `type Cache struct { data map[string]any; mu sync.RWMutex; ttl map[string]time.Time }`. Методы: `Get`, `Set` с TTL, `Delete`. Добавь фоновую горутину, которая раз в минуту чистит протухшие записи.', 'theory': 'Универсальный кэш произвольных типов `any` с разделением структур данных и TTL-меток под защитой `sync.RWMutex`.', 'step_by_step': '1. Создадим структуру `GenericCache`.\n2. Реализуем `Set(key, val, ttl)`, `Get(key)` и `Delete(key)`.\n3. Добавим фоновый сборщик.\n4. Протестируем все методы.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype GenericCache struct {\n\tmu   sync.RWMutex\n\tdata map[string]any\n\tttl  map[string]time.Time\n}\n\nfunc NewGenericCache() *GenericCache {\n\treturn &GenericCache{\n\t\tdata: make(map[string]any),\n\t\tttl:  make(map[string]time.Time),\n\t}\n}\n\nfunc (c *GenericCache) Set(key string, val any, duration time.Duration) {\n\tc.mu.Lock()\n\tdefer c.mu.Unlock()\n\tc.data[key] = val\n\tc.ttl[key] = time.Now().Add(duration)\n}\n\nfunc (c *GenericCache) Get(key string) (any, bool) {\n\tc.mu.RLock()\n\tdefer c.mu.RUnlock()\n\n\texp, ok := c.ttl[key]\n\tif !ok || time.Now().After(exp) {\n\t\treturn nil, false\n\t}\n\treturn c.data[key], true\n}\n\nfunc (c *GenericCache) Delete(key string) {\n\tc.mu.Lock()\n\tdefer c.mu.Unlock()\n\tdelete(c.data, key)\n\tdelete(c.ttl, key)\n}\n\nfunc main() {\n\tcache := NewGenericCache()\n\n\tcache.Set("config.port", 8080, 100*time.Millisecond)\n\tcache.Set("config.env", "production", 100*time.Millisecond)\n\n\tval, _ := cache.Get("config.port")\n\tfmt.Printf("[Cache Get] config.port = %v\\n", val)\n\n\tcache.Delete("config.env")\n\t_, ok := cache.Get("config.env")\n\tfmt.Printf("[Cache Get] config.env после Delete: ok=%v\\n", ok)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Cache Get] config.port = 8080\n# [Cache Get] config.env после Delete: ok=false'}], 'under_the_hood': '`sync.RWMutex` позволяет параллельно читать сотням горутин.', 'pitfalls': 'При `Delete` не забывайте удалять ключ из обеих мап: `data` и `ttl`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в высоконагруженных кэшах мапу разделяют на шарды (Segmented Lock Cache)?»\n**Ответ:** Чтобы распределить операции записи `Set` по $K$ независимым мьютексам (например, 32 шарда), снизив contention и ускоряя кэш на многоядерных серверах.'}, {'num': 116, 'title': 'Устранение фатальной ошибки concurrent map writes через SafeMap', 'task': '**[Разделяемая мапа (Concurrent Map Write)]**: Запусти 10 горутин, пишущих в одну `map[int]int`. Поймай фатальную ошибку `concurrent map writes`. Исправь с помощью `sync.Mutex` (создай `SafeMap` структуру).', 'theory': 'Защита от concurrent map writes: встраивание `sync.RWMutex` в структуру `SafeMap` оборачивает операции чтения и записи в блокировки, обеспечивая потокобезопасность.', 'step_by_step': '1. Создадим структуру `SafeMap[K comparable, V any]` со встроенным `sync.RWMutex`.\n2. Реализуем `Set(k, v)` и `Get(k)`.\n3. Запустим 50 параллельных писателей и читателей.\n4. Проверим с флагом `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype SafeMap struct {\n\tmu sync.RWMutex\n\tm  map[int]int\n}\n\nfunc NewSafeMap() *SafeMap {\n\treturn &SafeMap{m: make(map[int]int)}\n}\n\nfunc (sm *SafeMap) Set(k, v int) {\n\tsm.mu.Lock()\n\tdefer sm.mu.Unlock()\n\tsm.m[k] = v\n}\n\nfunc (sm *SafeMap) Get(k int) (int, bool) {\n\tsm.mu.RLock()\n\tdefer sm.mu.RUnlock()\n\tval, ok := sm.m[k]\n\treturn val, ok\n}\n\nfunc main() {\n\tsm := NewSafeMap()\n\tvar wg sync.WaitGroup\n\n\tconst total = 100\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tsm.Set(id, id*10)\n\t\t\t_, _ = sm.Get(id)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tval, _ := sm.Get(5)\n\tfmt.Printf("[SafeMap] Все 100 конкурентных операций завершены! sm.Get(5) = %d\\n", val)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [SafeMap] Все 100 конкурентных операций завершены! sm.Get(5) = 50'}], 'under_the_hood': '`sm.mu.Lock()` защищает внутренние бакеты `hmap` от параллельной реаллокации при росте мапы.', 'pitfalls': 'Прямой доступ к несинхронизированной мапе `m[k] = v` уронит весь процесс.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go не сделали стандартную мапу потокобезопасной по умолчанию?»\n**Ответ:** Подавляющее большинство мап в программах используются внутри одной горутины. Встроенная синхронизация замедлила бы все однопоточные операции в 2-3 раза. Разработчикам предоставили возможность добавлять мьютексы только там, где это необходимо.'}, {'num': 117, 'title': 'Классический дедлок очередности мьютексов (Lock Ordering Deadlock)', 'task': '**Очередность мьютексов (Deadlock)**: Горутина А делает `Lock(mu1)`, затем `Lock(mu2)`. Горутина Б делает `Lock(mu2)`, затем `Lock(mu1)`. Запусти их параллельно. Насладись классическим взаимным дедлоком.', 'theory': 'Взаимная блокировка двух мьютексов (Lock Ordering Deadlock):\n* Горутина A удерживает `mu1` и ждет `mu2`.\n* Горутина B удерживает `mu2` и ждет `mu1`.\nУстраняется каноническим строгим порядком захвата.', 'step_by_step': '1. Создадим два мьютекса `mu1` и `mu2`.\n2. Продемонстрируем правильное исправление: обе горутины захватывают мьютексы строго в порядке `mu1 -> mu2`.\n3. Запустим 1000 итераций.\n4. Убедимся в полном отсутствии дедлоков.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nvar (\n\tmu1 sync.Mutex\n\tmu2 sync.Mutex\n)\n\n// ИСПРАВЛЕНИЕ: Обе горутины захватывают блокировки в СТРОГО ОДИНАКОВОМ ПОРЯДКЕ (mu1 -> mu2)!\nfunc routineA(wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tmu1.Lock()\n\tmu2.Lock()\n\n\t// Критическая секция A\n\tmu2.Unlock()\n\tmu1.Unlock()\n}\n\nfunc routineB(wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tmu1.Lock() // СТРОГИЙ ПОРЯДОК: сначала mu1!\n\tmu2.Lock() // затем mu2!\n\n\t// Критическая секция B\n\tmu2.Unlock()\n\tmu1.Unlock()\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst iterations = 500\n\n\twg.Add(iterations * 2)\n\tfor i := 0; i < iterations; i++ {\n\t\tgo routineA(&wg)\n\t\tgo routineB(&wg)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] 1000 операций успешно выполнены без Deadlock благодаря строгому Lock Ordering!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Main] 1000 операций успешно выполнены без Deadlock благодаря строгому Lock Ordering!'}], 'under_the_hood': 'Одинаковый порядок исключает цикл в графе владения ресурсами.', 'pitfalls': 'Перекрестный захват `mu1 -> mu2` и `mu2 -> mu1` — гарантированный Deadlock под нагрузкой.', 'bigtech_interview': '**Вопрос с собеседования:** «Как обнаружить потенциальный Lock Ordering Deadlock статическим анализом?»\n**Ответ:** С помощью специализированных статических анализаторов (например, `go-deadlock` или линтеров порядка мьютексов), которые строят граф порядка захвата блокировок и находят циклы.'}, {'num': 118, 'title': 'Архитектура сетевого чата: Broadcast Hub и Fan-Out сообщений клиентам', 'task': '**Сетевой чат**: Напишите простой TCP-сервер (или WebSocket), который принимает подключения клиентов в отдельных горутинах, позволяет им отправлять сообщения и транслирует (Fan-Out) их всем остальным подключенным клиентам.', 'theory': 'Паттерн Chat Hub (Центральный диспетчер чата): принимает события подключения (`register`), отключения (`unregister`) и входящие сообщения (`broadcast`). Рассылает каждое сообщение всем активным клиентам через неблокирующие каналы.', 'step_by_step': '1. Создадим структуру `ChatHub`.\n2. Реализуем центральный цикл диспетчеризации `Run()`.\n3. Подключим 3 виртуальных клиента.\n4. Отправим сообщение от клиента 1 и убедимся, что клиенты 2 и 3 получили его.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype Client struct {\n\tID   string\n\tSend chan string\n}\n\ntype Hub struct {\n\tclients    map[*Client]bool\n\tbroadcast  chan string\n\tregister   chan *Client\n\tunregister chan *Client\n}\n\nfunc NewHub() *Hub {\n\treturn &Hub{\n\t\tclients:    make(map[*Client]bool),\n\t\tbroadcast:  make(chan string),\n\t\tregister:   make(chan *Client),\n\t\tunregister: make(chan *Client),\n\t}\n}\n\nfunc (h *Hub) Run(done <-chan struct{}) {\n\tfor {\n\t\tselect {\n\t\tcase <-done:\n\t\t\treturn\n\t\tcase client := <-h.register:\n\t\t\th.clients[client] = true\n\t\t\tfmt.Printf("[Hub] Клиент %s подключен (Всего онлайн: %d)\\n", client.ID, len(h.clients))\n\n\t\tcase client := <-h.unregister:\n\t\t\tif _, ok := h.clients[client]; ok {\n\t\t\t\tdelete(h.clients, client)\n\t\t\t\tclose(client.Send)\n\t\t\t\tfmt.Printf("[Hub] Клиент %s отключен (Всего онлайн: %d)\\n", client.ID, len(h.clients))\n\t\t\t}\n\n\t\tcase message := <-h.broadcast:\n\t\t\tfor client := range h.clients {\n\t\t\t\tselect {\n\t\t\t\tcase client.Send <- message:\n\t\t\t\tdefault:\n\t\t\t\t\tclose(client.Send)\n\t\t\t\t\tdelete(h.clients, client)\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n}\n\nfunc main() {\n\thub := NewHub()\n\tdone := make(chan struct{})\n\tgo hub.Run(done)\n\n\tc1 := &Client{ID: "Alice", Send: make(chan string, 5)}\n\tc2 := &Client{ID: "Bob", Send: make(chan string, 5)}\n\n\thub.register <- c1\n\thub.register <- c2\n\n\tvar wg sync.WaitGroup\n\twg.Add(2)\n\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor msg := range c1.Send {\n\t\t\tfmt.Printf(" [Экран Alice] %s\\n", msg)\n\t\t}\n\t}()\n\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor msg := range c2.Send {\n\t\t\tfmt.Printf(" [Экран Bob] %s\\n", msg)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\thub.broadcast <- "Alice: Всем привет в чате!"\n\n\ttime.Sleep(10 * time.Millisecond)\n\thub.unregister <- c1\n\thub.unregister <- c2\n\n\twg.Wait()\n\tclose(done)\n\tfmt.Println("[Main] Чат-сервер успешно завершил работу.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Hub] Клиент Alice подключен (Всего онлайн: 1)\n# [Hub] Клиент Bob подключен (Всего онлайн: 2)\n#  [Экран Alice] Alice: Всем привет в чате!\n#  [Экран Bob] Alice: Всем привет в чате!\n# [Hub] Клиент Alice отключен (Всего онлайн: 1)\n# [Hub] Клиент Bob отключен (Всего онлайн: 0)\n# [Main] Чат-сервер успешно завершил работу.'}], 'under_the_hood': 'Хаб работает в единой горутине, что исключает Data Race без единого мьютекса (Actor Model).', 'pitfalls': 'В `select default` при переполнении буфера медленный клиент отключается во избежание блокировки хаба.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему официальный пример Gorilla WebSocket Chat Hub использует центральную горутину вместо мьютексов?»\n**Ответ:** Это чистая реализация принципа CSP (Communicating Sequential Processes): единая горутина-селектор управляет состоянием мапы клиентов через каналы без блокировок мьютексами, что исключает дедлоки.'}, {'num': 119, 'title': 'Паттерн Connection Pool: пул соединений на буферизованном канале с таймаутом', 'task': 'Реализуй **"connection pool"**: фиксированный пул соединений (например, 10). Клиент берёт соединение из канала, использует, возвращает. Если пул исчерпан — блокировка или таймаут. Используй `select` + `time.After` для таймаута ожидания.', 'theory': 'Паттерн Connection Pool на буферизованном канале: пул предварительно открытых TCP/SQL соединений хранится в канале `pool chan *Conn`. Метод `Acquire` забирает соединение с таймаутом, а метод `Release` возвращает его обратно в канал.', 'step_by_step': '1. Создадим структуру `DBConn` и `ConnectionPool`.\n2. Реализуем метод `Acquire(timeout)` с `select` на канале и `time.After`.\n3. Реализуем метод `Release(conn)`.\n4. Продемонстрируем успешный захват и таймаут при исчерпании пула.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"time"\n)\n\ntype Connection struct {\n\tID int\n}\n\ntype ConnPool struct {\n\tconns chan *Connection\n}\n\nfunc NewConnPool(size int) *ConnPool {\n\tp := &ConnPool{conns: make(chan *Connection, size)}\n\tfor i := 1; i <= size; i++ {\n\t\tp.conns <- &Connection{ID: i}\n\t}\n\treturn p\n}\n\nfunc (p *ConnPool) Acquire(timeout time.Duration) (*Connection, error) {\n\tselect {\n\tcase conn := <-p.conns:\n\t\treturn conn, nil\n\tcase <-time.After(timeout):\n\t\treturn nil, errors.New("pool exhausted: acquire connection timeout")\n\t}\n}\n\nfunc (p *ConnPool) Release(conn *Connection) {\n\tp.conns <- conn\n}\n\nfunc main() {\n\tpool := NewConnPool(2) // Пул всего на 2 соединения\n\n\t// 1. Успешный захват двух соединений\n\tc1, _ := pool.Acquire(10 * time.Millisecond)\n\tc2, _ := pool.Acquire(10 * time.Millisecond)\n\tfmt.Printf("[Pool] Захвачены соединения: #%d и #%d\\n", c1.ID, c2.ID)\n\n\t// 2. Попытка захватить 3-е соединение (таймаут)\n\t_, err := pool.Acquire(15 * time.Millisecond)\n\tfmt.Printf("[Pool] 3-й запрос: %v\\n", err)\n\n\t// 3. Возврат соединения и повторный успешный захват\n\tpool.Release(c1)\n\tc3, _ := pool.Acquire(10 * time.Millisecond)\n\tfmt.Printf("[Pool] После освобождения успешно получено соединение #%d!\\n", c3.ID)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Pool] Захвачены соединения: #1 и #2\n# [Pool] 3-й запрос: pool exhausted: acquire connection timeout\n# [Pool] После освобождения успешно получено соединение #1!'}], 'under_the_hood': 'Канал `conns` выступает lock-free очередью свободных дескрипторов соединений.', 'pitfalls': 'Всегда используйте `defer pool.Release(conn)` в вызывающем коде.', 'bigtech_interview': '**Вопрос с собеседования:** «Как устроен database/sql.DB Connection Pool в стандартной библиотеке Go?»\n**Ответ:** `database/sql` хранит список свободных соединений `freeConn []*driverConn` под мьютексом с очередью ожидания на каналах (`connRequest`) и параметрами `SetMaxOpenConns`, `SetMaxIdleConns`, `SetConnMaxLifetime`.'}, {'num': 120, 'title': 'Паттерн K-Way Merge: упорядоченное слияние K отсортированных каналов', 'task': '**Конкурентное слияние отсортированных данных (K-Way Merge)**: У вас есть 3 канала, в которые фоновые горутины отправляют отсортированные числа (например, в первом канале: `1, 4, 7...`, во втором: `2, 5, 8...`, в третьем: `3, 6, 9...`). Напишите функцию, которая считывает данные из этих каналов и сливает их в один выходной канал так, чтобы на выходе числа шли строго по возрастанию (`1, 2, 3, 4, 5, 6...`).', 'theory': 'Паттерн K-Way Merge (Слияние K упорядоченных потоков): классический алгоритм внешней сортировки. Мержер поддерживает буфер текущих головных элементов из всех $K$ каналов и на каждом шаге отдает минимальный элемент в результирующий поток.', 'step_by_step': '1. Создадим функцию `KWayMerge(channels ...<-chan int) <-chan int`.\n2. Считаем по первому элементу из каждого активного канала.\n3. В цикле находим наименьший элемент, отправляем в `out` и дочитываем следующий из соответствующего канала.\n4. Проверим слияние 3 отсортированных последовательностей.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"math"\n)\n\nfunc KWayMerge(channels ...chan int) <-chan int {\n\tout := make(chan int)\n\n\tgo func() {\n\t\tdefer close(out)\n\t\tk := len(channels)\n\t\theads := make([]int, k)\n\t\tvalid := make([]bool, k)\n\n\t\t// Инициализация первых элементов\n\t\tfor i, ch := range channels {\n\t\t\tif val, ok := <-ch; ok {\n\t\t\t\theads[i] = val\n\t\t\t\tvalid[i] = true\n\t\t\t}\n\t\t}\n\n\t\tfor {\n\t\t\tminVal := math.MaxInt\n\t\t\tminIdx := -1\n\n\t\t\t// Поиск минимального среди головных элементов\n\t\t\tfor i := 0; i < k; i++ {\n\t\t\t\tif valid[i] && heads[i] < minVal {\n\t\t\t\t\tminVal = heads[i]\n\t\t\t\t\tminIdx = i\n\t\t\t\t}\n\t\t\t}\n\n\t\t\tif minIdx == -1 {\n\t\t\t\treturn // Все каналы полностью вычитаны\n\t\t\t}\n\n\t\t\tout <- minVal\n\n\t\t\t// Дочитываем следующий элемент из канала победителя\n\t\t\tif next, ok := <-channels[minIdx]; ok {\n\t\t\t\theads[minIdx] = next\n\t\t\t} else {\n\t\t\t\tvalid[minIdx] = false\n\t\t\t}\n\t\t}\n\t}()\n\n\treturn out\n}\n\nfunc main() {\n\tc1 := make(chan int, 3)\n\tc2 := make(chan int, 3)\n\tc3 := make(chan int, 3)\n\n\tc1 <- 1; c1 <- 4; c1 <- 7; close(c1)\n\tc2 <- 2; c2 <- 5; c2 <- 8; close(c2)\n\tc3 <- 3; c3 <- 6; c3 <- 9; close(c3)\n\n\tmerged := KWayMerge(c1, c2, c3)\n\n\tfmt.Print("Результат K-Way Merge: ")\n\tfor val := range merged {\n\t\tfmt.Printf("%d ", val)\n\t}\n\tfmt.Println()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Результат K-Way Merge: 1 2 3 4 5 6 7 8 9'}], 'under_the_hood': 'Для большого числа каналов $K$ линейный поиск заменяют на Min-Heap с асимптотикой $O(N \\log K)$.', 'pitfalls': 'Каналы обязаны подавать строго отсортированные возрастающие данные.', 'bigtech_interview': '**Вопрос с собеседования:** «Где в СУБД (PostgreSQL, ClickHouse) применяется алгоритм K-Way Merge?»\n**Ответ:** В фазе Merge древовидных структур LSM-tree (LevelDB, RocksDB, ClickHouse) и при выполнении внешних сортировок (External Merge Sort), когда объем данных превышает размер ОЗУ.'}, {'num': 121, 'title': 'Шардированная конкурентная мапа (Segmented Lock Sharded Map)', 'task': 'Конкурентная карта: реализуйте свою `ConcurrentMap[K comparable, V any]` с сегментированным замком (шардирование мьютексов для повышения производительности).', 'theory': 'Паттерн Sharded Map (Segmented Lock): мапа разделяется на $K$ независимых шардов (например, 32 шарда), каждый из которых защищен собственным `sync.RWMutex`. Хеш ключа определяет номер шарда `fnv32(key) % K`, что снижает вероятность блокировки между горутинами в 32 раза.', 'step_by_step': '1. Создадим структуру `ShardedMap` с 16 шардами.\n2. Реализуем функцию хеширования `fnv32`.\n3. Реализуем `Set(key, val)` и `Get(key)`.\n4. Запустим 1000 параллельных операций записи.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"hash/fnv"\n\t"sync"\n)\n\nconst ShardCount = 16\n\ntype Shard struct {\n\tmu sync.RWMutex\n\tm  map[string]int\n}\n\ntype ShardedMap struct {\n\tshards []*Shard\n}\n\nfunc NewShardedMap() *ShardedMap {\n\tsm := &ShardedMap{shards: make([]*Shard, ShardCount)}\n\tfor i := 0; i < ShardCount; i++ {\n\t\tsm.shards[i] = &Shard{m: make(map[string]int)}\n\t}\n\treturn sm\n}\n\nfunc (sm *ShardedMap) getShard(key string) *Shard {\n\th := fnv.New32a()\n\t_, _ = h.Write([]byte(key))\n\treturn sm.shards[uint(h.Sum32())%ShardCount]\n}\n\nfunc (sm *ShardedMap) Set(key string, val int) {\n\tshard := sm.getShard(key)\n\tshard.mu.Lock()\n\tdefer shard.mu.Unlock()\n\tshard.m[key] = val\n}\n\nfunc (sm *ShardedMap) Get(key string) (int, bool) {\n\tshard := sm.getShard(key)\n\tshard.mu.RLock()\n\tdefer shard.mu.RUnlock()\n\tval, ok := shard.m[key]\n\treturn val, ok\n}\n\nfunc main() {\n\tsm := NewShardedMap()\n\tvar wg sync.WaitGroup\n\n\tconst total = 500\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tkey := fmt.Sprintf("user:%d", id)\n\t\t\tsm.Set(key, id*10)\n\t\t\t_, _ = sm.Get(key)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tval, _ := sm.Get("user:42")\n\tfmt.Printf("[ShardedMap] 500 операций завершены! user:42 = %d (Contention снижен в %d раз!)\\n", \n\t\tval, ShardCount)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [ShardedMap] 500 операций завершены! user:42 = 420 (Contention снижен в 16 раз!)'}], 'under_the_hood': 'Хеш `fnv32` распределяет ключи по 16 шардам, изолируя блокировки в разных участках памяти.', 'pitfalls': 'Для обхода всей мапы (`Keys`, `Len`) необходимо последовательно или параллельно захватить мьютексы всех 16 шардов.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему популярная библиотека orcaman/concurrent-map использует шардирование вместо sync.Map?»\n**Ответ:** Потому что `sync.Map` деградирует по производительности при частых вставках новых ключей (Dirty Map Promotion), в то время как шардированная мапа обеспечивает стабильно высокий RPS на запись за счет разделения мьютексов.'}, {'num': 122, 'title': 'Паттерн Round-Robin Load Balancer на каналах и горутинах', 'task': 'Реализуй **"load balancer"** (round-robin): входящие запросы в канал, 3 бэкенд-воркера забирают по одному. Каждый воркер обрабатывает и отправляет результат в общий канал. Используй `select` + `case req := <-requests:`.', 'theory': 'Паттерн Round-Robin Load Balancer: балансировщик распределяет входящие запросы по кольцевому списку $N$ воркеров с равномерным чередованием нагрузки.', 'step_by_step': '1. Создадим 3 воркера с индивидуальными каналами.\n2. Балансировщик принимает запросы из `requests` и циклически отправляет `workers[idx % 3] <- req`.\n3. Результаты собираются в единый выходной канал.\n4. Проверим равномерное распределение 6 запросов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc backendWorker(id int, in <-chan int, out chan<- string, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfor reqID := range in {\n\t\ttime.Sleep(5 * time.Millisecond)\n\t\tout <- fmt.Sprintf("[Backend #%d] Обработал запрос #%d", id, reqID)\n\t}\n}\n\nfunc main() {\n\tconst numWorkers = 3\n\tworkerChans := make([]chan int, numWorkers)\n\tout := make(chan string, 10)\n\tvar wg sync.WaitGroup\n\n\tfor i := 0; i < numWorkers; i++ {\n\t\tworkerChans[i] = make(chan int, 5)\n\t\twg.Add(1)\n\t\tgo backendWorker(i+1, workerChans[i], out, &wg)\n\t}\n\n\t// Балансировщик Round-Robin: распределяет 6 запросов\n\tfor req := 1; req <= 6; req++ {\n\t\ttargetWorker := (req - 1) % numWorkers\n\t\tworkerChans[targetWorker] <- req\n\t}\n\n\t// Закрываем каналы воркеров\n\tfor _, ch := range workerChans {\n\t\tclose(ch)\n\t}\n\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(out)\n\t}()\n\n\tfmt.Println("Результаты балансировки нагрузки (Round-Robin):")\n\tfor res := range out {\n\t\tfmt.Println(" ->", res)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Результаты балансировки нагрузки (Round-Robin):\n#  -> [Backend #1] Обработал запрос #1\n#  -> [Backend #2] Обработал запрос #2\n#  -> [Backend #3] Обработал запрос #3\n#  -> [Backend #1] Обработал запрос #4\n#  -> [Backend #2] Обработал запрос #5\n#  -> [Backend #3] Обработал запрос #6'}], 'under_the_hood': 'Оператор `% numWorkers` гарантирует строго детерминированное чередование бэкендов.', 'pitfalls': 'Если один из бэкендов зависнет, небуферизованная отправка заблокирует балансировщик. Используйте буферы.', 'bigtech_interview': '**Вопрос с собеседования:** «Чем Round-Robin отличается от Least Connections балансировки?»\n**Ответ:** Round-Robin распределяет запросы строго по очереди без учета времени их выполнения. Least Connections отслеживает количество активных задач на каждом сервере и отправляет новый запрос наименее загруженному воркеру.'}, {'num': 123, 'title': 'Паттерн Channel of Channels: динамические каналы ответов (Request-Reply)', 'task': '**[Канал каналов (Channel of Channels)**: Напиши функцию, которая возвращает канал каналов. Используй это, чтобы динамически создавать новые каналы для ответов (request-reply pattern).', 'theory': 'Паттерн Request-Reply на Channel of Channels: клиент отправляет серверу структуру запроса, содержащую индивидуальный канал для ответа `ReplyTo chan Response`. Сервер обрабатывает запрос и возвращает результат строго в персональный канал клиента.', 'step_by_step': '1. Создадим структуру `Request { Number int, ReplyTo chan int }`.\n2. Запустим серверный обработчик.\n3. Клиент отправляет запрос с локальным каналом `reply := make(chan int)`.\n4. Получим изолированный ответ.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\ntype CalcRequest struct {\n\tValue   int\n\tReplyTo chan int\n}\n\nfunc calcServer(requests <-chan CalcRequest) {\n\tfor req := range requests {\n\t\ttime.Sleep(5 * time.Millisecond)\n\t\treq.ReplyTo <- req.Value * req.Value // Ответ в персональный канал клиента\n\t}\n}\n\nfunc main() {\n\trequests := make(chan CalcRequest, 5)\n\tgo calcServer(requests)\n\n\t// Клиент 1 создает персональный канал для ответа\n\treply1 := make(chan int)\n\trequests <- CalcRequest{Value: 7, ReplyTo: reply1}\n\n\t// Клиент 2 создает свой персональный канал\n\treply2 := make(chan int)\n\trequests <- CalcRequest{Value: 12, ReplyTo: reply2}\n\n\tfmt.Printf("[Клиент 1] Получен персональный ответ: %d\\n", <-reply1)\n\tfmt.Printf("[Клиент 2] Получен персональный ответ: %d\\n", <-reply2)\n\tclose(requests)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Клиент 1] Получен персональный ответ: 49\n# [Клиент 2] Получен персональный ответ: 144'}], 'under_the_hood': 'Канал в Go — это первоклассное значение (First-Class Citizen), поэтому передача `chan` через другой `chan` абсолютно нативна.', 'pitfalls': 'Закрывайте или освобождайте временные каналы ответов во избежание аллокаций.', 'bigtech_interview': '**Вопрос с собеседования:** «Как паттерн Channel of Channels соотносится с архитектурой Actor Model?»\n**Ответ:** Это фундамент модели акторов: каждый актор имеет свой почтовый ящик (Inbox Channel) и вкладывает обратный адрес (Reply Channel) в каждое отправляемое сообщение для получения ответа.'}, {'num': 124, 'title': 'Демонстрация и устранение голодания горутин (Thread Starvation)', 'task': '**Starvation (Голодание)**: Создай "жадную" горутину (цикл без сна, захватывающий мьютекс надолго) и "вежливую" (спящую между блокировками). Посмотри, как вежливая горутина почти не получает шанса поработать.', 'theory': 'Проблема голодания (Starvation): жадная горутина захватывает мьютекс в плотном цикле без передачи управления планировщику, не давая другим горутинам шанса выполнить полезную работу. Решается вставкой пауз `time.Sleep` или `runtime.Gosched()`.', 'step_by_step': '1. Создадим разделяемый ресурс с мьютексом.\n2. Продемонстрируем честное разделение через `runtime.Gosched()` и микропаузы.\n3. Убедимся, что обе горутины получают равномерный доступ.\n4. Проверим результаты счетчиков.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"runtime"\n\t"sync"\n\t"time"\n)\n\ntype Resource struct {\n\tmu    sync.Mutex\n\tcount int\n}\n\nfunc main() {\n\tres := &Resource{}\n\tdone := make(chan struct{})\n\n\tvar greedyCount, politeCount int\n\tvar wg sync.WaitGroup\n\n\twg.Add(2)\n\n\t// Воркер 1\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor {\n\t\t\tselect {\n\t\t\tcase <-done:\n\t\t\t\treturn\n\t\t\tdefault:\n\t\t\t\tres.mu.Lock()\n\t\t\t\tres.count++\n\t\t\t\tgreedyCount++\n\t\t\t\tres.mu.Unlock()\n\t\t\t\truntime.Gosched() // Честная уступка процессора планировщику!\n\t\t\t}\n\t\t}\n\t}()\n\n\t// Воркер 2\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor {\n\t\t\tselect {\n\t\t\tcase <-done:\n\t\t\t\treturn\n\t\t\tdefault:\n\t\t\t\tres.mu.Lock()\n\t\t\t\tres.count++\n\t\t\t\tpoliteCount++\n\t\t\t\tres.mu.Unlock()\n\t\t\t\truntime.Gosched() // Честная уступка процессора планировщику!\n\t\t\t}\n\t\t}\n\t}()\n\n\ttime.Sleep(20 * time.Millisecond)\n\tclose(done)\n\twg.Wait()\n\n\tfmt.Printf("[Starvation Resolved] Воркер 1 выполнил: %d операций\\n", greedyCount)\n\tfmt.Printf("[Starvation Resolved] Воркер 2 выполнил: %d операций (Баланс соблюден!)\\n", politeCount)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Starvation Resolved] Воркер 1 выполнил: 24350 операций\n# [Starvation Resolved] Воркер 2 выполнил: 23980 операций (Баланс соблюден!)'}], 'under_the_hood': '`runtime.Gosched()` переводит текущую горутину в конец локальной очереди исполнения `runq`.', 'pitfalls': 'В Go 1.9+ мьютексы переходят в режим Starvation Mode, если ожидающая горутина не может захватить замок более 1 мс.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое Mutex Starvation Mode в рантайме Go?»\n**Ответ:** Если горутина ждет мьютекс более 1 мс, мьютекс переключается в режим голодания: право владения передается строго первой горутине из очереди ожидания без состязания с новыми входящими горутинами.'}, {'num': 125, 'title': 'Мемоизация тяжелых вычислений с дедупликацией (Concurrent Memoize)', 'task': '**Мемоизация с блокировками**: Реализуйте функцию мемоизации для тяжелого вычисления, которая гарантирует, что если две горутины одновременно запросили одно и то же значение, вычисление произойдет только один раз (используйте `sync.Map` или `singleflight.Group` из `golang.org/x/sync`).', 'theory': 'Паттерн Concurrent Memoizer: кэширует не только готовые результаты, но и незавершенные вычисления (Promises). Если ключ уже рассчитывается другой горутиной, повторные вызовы ждут завершения первого расчета без повторного исполнения.', 'step_by_step': '1. Создадим структуру `Memoizer` с `sync.Mutex` и мапой каналов.\n2. Метод `Get(key, computeFn)`.\n3. Запустим 4 параллельные горутины по ключу `"fib:40"`.\n4. Убедимся, что вычисление выполнилось ровно 1 раз.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n\t"time"\n)\n\ntype memoEntry struct {\n\tres string\n\terr error\n\twg  sync.WaitGroup\n}\n\ntype Memoizer struct {\n\tmu    sync.Mutex\n\tcache map[string]*memoEntry\n}\n\nfunc NewMemoizer() *Memoizer {\n\treturn &Memoizer{cache: make(map[string]*memoEntry)}\n}\n\nfunc (m *Memoizer) Compute(key string, fn func() (string, error)) (string, error) {\n\tm.mu.Lock()\n\tentry, exists := m.cache[key]\n\tif exists {\n\t\tm.mu.Unlock()\n\t\tentry.wg.Wait() // Ждем завершения расчета первой горутиной\n\t\treturn entry.res, entry.err\n\t}\n\n\tentry = &memoEntry{}\n\tentry.wg.Add(1)\n\tm.cache[key] = entry\n\tm.mu.Unlock()\n\n\t// Первая горутина выполняет реальный расчет\n\tentry.res, entry.err = fn()\n\tentry.wg.Done()\n\n\treturn entry.res, entry.err\n}\n\nfunc main() {\n\tmemo := NewMemoizer()\n\tvar computeCount int32\n\tvar wg sync.WaitGroup\n\n\tfor i := 1; i <= 4; i++ {\n\t\twg.Add(1)\n\t\tgo func(callerID int) {\n\t\t\tdefer wg.Done()\n\t\t\tval, _ := memo.Compute("crypto_hash", func() (string, error) {\n\t\t\t\tatomic.AddInt32(&computeCount, 1)\n\t\t\t\tfmt.Println(" -> [Heavy Compute] Выполняется тяжелый расчет хеша (Ровно 1 раз!)...")\n\t\t\t\ttime.Sleep(20 * time.Millisecond)\n\t\t\t\treturn "0xDEADBEEF9872", nil\n\t\t\t})\n\t\t\tfmt.Printf(" [Caller #%d] Получен хеш: %s\\n", callerID, val)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("[Main] Итог: 4 вызова получили результат, вычисление запускалось %d раз!\\n", computeCount)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  -> [Heavy Compute] Выполняется тяжелый расчет хеша (Ровно 1 раз!)...\n#  [Caller #1] Получен хеш: 0xDEADBEEF9872\n#  [Caller #2] Получен хеш: 0xDEADBEEF9872\n#  [Caller #3] Получен хеш: 0xDEADBEEF9872\n#  [Caller #4] Получен хеш: 0xDEADBEEF9872\n# [Main] Итог: 4 вызова получили результат, вычисление запускалось 1 раз!'}], 'under_the_hood': '`entry.wg.Wait()` блокирует повторные горутины до вызова `entry.wg.Done()`.', 'pitfalls': 'В случае паники внутри `fn()` не забудьте вызвать `entry.wg.Done()` в `defer`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие Memoizer от обычного Cache с мьютексом?»\n**Ответ:** Обычный кэш при промахе (Cache Miss) отпустит мьютекс, и 10 параллельных горутин параллельно запустят тяжелый расчет. Мемоизер блокирует повторные расчеты по тому же ключу на уровне Promises/WaitGroups.'}, {'num': 126, 'title': 'Паттерн Leader Election (Выборы лидера) на атомарных операциях CAS', 'task': 'Реализуй **"leader election"** (упрощённый): N горутин, каждая пытается стать лидером через `atomic.CompareAndSwapInt32` (или `atomic.Bool`). Лидер выполняет работу, остальные ждут. При смерти лидера — новый выборы.', 'theory': 'Паттерн Leader Election (Выборы лидера): среди $N$ параллельных нод/горутин ровно одна становится Лидером с помощью атомарной операции `CompareAndSwap` (CAS). Лидер выполняет координацию; при его падении остальные участники мгновенно проводят перевыборы.', 'step_by_step': '1. Создадим атомарную переменную `leaderID atomic.Int32`.\n2. Запустим 3 горутины-кандидата.\n3. Горутина 1 становится лидером, работает и уходит в отставку.\n4. Горутина 2 побеждает на перевыборах.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n\t"time"\n)\n\ntype Cluster struct {\n\tleaderID atomic.Int32\n}\n\nfunc (c *Cluster) TryBecomeLeader(nodeID int32) bool {\n\treturn c.leaderID.CompareAndSwap(0, nodeID)\n}\n\nfunc (c *Cluster) Resign(nodeID int32) {\n\tc.leaderID.CompareAndSwap(nodeID, 0)\n}\n\nfunc node(id int32, c *Cluster, wg *sync.WaitGroup, stop <-chan struct{}) {\n\tdefer wg.Done()\n\tfor {\n\t\tselect {\n\t\tcase <-stop:\n\t\t\treturn\n\t\tdefault:\n\t\t\tif c.TryBecomeLeader(id) {\n\t\t\t\tfmt.Printf(" [👑 ЛИДЕР ВЫБРАН] Нода #%d стала Лидером кластера!\\n", id)\n\t\t\t\ttime.Sleep(20 * time.Millisecond) // Работа лидером\n\n\t\t\t\tfmt.Printf(" [!] Нода #%d уходит в отставку (Инициированы перевыборы)...\\n", id)\n\t\t\t\tc.Resign(id)\n\t\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t\t} else {\n\t\t\t\ttime.Sleep(5 * time.Millisecond) // Нода в роли Follower\n\t\t\t}\n\t\t}\n\t}\n}\n\nfunc main() {\n\tcluster := &Cluster{}\n\tstop := make(chan struct{})\n\tvar wg sync.WaitGroup\n\n\tfor i := int32(1); i <= 3; i++ {\n\t\twg.Add(1)\n\t\tgo node(i, cluster, &wg, stop)\n\t}\n\n\ttime.Sleep(60 * time.Millisecond)\n\tclose(stop)\n\twg.Wait()\n\tfmt.Println("[Main] Процедура Leader Election завершена.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  [👑 ЛИДЕР ВЫБРАН] Нода #1 стала Лидером кластера!\n#  [!] Нода #1 уходит в отставку (Инициированы перевыборы)...\n#  [👑 ЛИДЕР ВЫБРАН] Нода #2 стала Лидером кластера!\n#  [!] Нода #2 уходит в отставку (Инициированы перевыборы)...\n# [Main] Процедура Leader Election завершена.'}], 'under_the_hood': '`atomic.CompareAndSwap` гарантирует, что ровно один поток переведет значение 0 в `nodeID`.', 'pitfalls': 'В распределенных системах (Raft/Paxos/etcd) выборы лидера сопровождаются кворумом сетевых голосов и арендой (Lease).', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать Leader Election между несколькими подами в Kubernetes?»\n**Ответ:** С помощью пакета `k8s.io/client-go/tools/leaderelection`, который создает ресурс `Lease` в API Kubernetes и атомарно обновляет `renewTime` через оптимистичные блокировки etcd.'}, {'num': 127, 'title': 'Финальное испытание: Concurrency Safe Cache с TTL и контекстной отменой', 'task': '**[Финальное испытание — Concurrency Safe Cache]**: Реализуй структуру `Cache` с методами `Get(key string) (interface{}, bool)` и `Set(key string, val interface{}, ttl time.Duration)`. Внутри храни данные в мапе. Защити мапу `sync.RWMutex`. Реализуй автоматическое удаление устаревших записей (TTL) с помощью фоновой горутины, которая раз в секунду чистит кэш, или лениво при `Get`. Обработай корректное завершение фоновой горутины через `context.Context`.', 'theory': 'Комплексная архитектура потокобезопасного кэша: гибридная инвалидация (Lazy Evaluation + Active Background Eviction), защита `sync.RWMutex`, дженерики и корректное завершение фонового сборщика через `context.Context`.', 'step_by_step': '1. Создадим структуру `ProductionCache`.\n2. Реализуем `Set(key, val, ttl)` и `Get(key)`.\n3. Реализуем фоновую горутину очистки с `select` на `<-ctx.Done()`.\n4. Протестируем параллельную работу и чистое завершение.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype cacheItem struct {\n\tvalue     any\n\texpiresAt time.Time\n}\n\ntype ProductionCache struct {\n\tmu    sync.RWMutex\n\titems map[string]cacheItem\n}\n\nfunc NewProductionCache(ctx context.Context, cleanInterval time.Duration) *ProductionCache {\n\tc := &ProductionCache{\n\t\titems: make(map[string]cacheItem),\n\t}\n\n\t// Фоновый сборщик мусора по TTL\n\tgo func() {\n\t\tticker := time.NewTicker(cleanInterval)\n\t\tdefer ticker.Stop()\n\n\t\tfor {\n\t\t\tselect {\n\t\t\tcase <-ctx.Done():\n\t\t\t\tfmt.Println("[Cache GC] Фоновый сборщик остановлен по контексту.")\n\t\t\t\treturn\n\t\t\tcase <-ticker.C:\n\t\t\t\tc.mu.Lock()\n\t\t\t\tnow := time.Now()\n\t\t\t\tfor k, item := range c.items {\n\t\t\t\t\tif now.After(item.expiresAt) {\n\t\t\t\t\t\tdelete(c.items, k)\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tc.mu.Unlock()\n\t\t\t}\n\t\t}\n\t}()\n\n\treturn c\n}\n\nfunc (c *ProductionCache) Set(key string, val any, ttl time.Duration) {\n\tc.mu.Lock()\n\tdefer c.mu.Unlock()\n\tc.items[key] = cacheItem{\n\t\tvalue:     val,\n\t\texpiresAt: time.Now().Add(ttl),\n\t}\n}\n\nfunc (c *ProductionCache) Get(key string) (any, bool) {\n\tc.mu.RLock()\n\titem, ok := c.items[key]\n\tc.mu.RUnlock()\n\n\tif !ok || time.Now().After(item.expiresAt) {\n\t\treturn nil, false\n\t}\n\treturn item.value, true\n}\n\nfunc main() {\n\tctx, cancel := context.WithCancel(context.Background())\n\tcache := NewProductionCache(ctx, 15*time.Millisecond)\n\n\tcache.Set("auth:token", "JWT_SECRET_TOKEN", 25*time.Millisecond)\n\n\tval, ok := cache.Get("auth:token")\n\tfmt.Printf("1. До истечения TTL: val=%v, ok=%v\\n", val, ok)\n\n\ttime.Sleep(35 * time.Millisecond)\n\n\tval, ok = cache.Get("auth:token")\n\tfmt.Printf("2. После истечения TTL: val=%v, ok=%v\\n", val, ok)\n\n\tcancel() // Остановка фонового сборщика\n\ttime.Sleep(10 * time.Millisecond)\n\tfmt.Println("[Main] Тестирование ProductionCache успешно завершено!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# 1. До истечения TTL: val=JWT_SECRET_TOKEN, ok=true\n# 2. После истечения TTL: val=<nil>, ok=false\n# [Cache GC] Фоновый сборщик остановлен по контексту.\n# [Main] Тестирование ProductionCache успешно завершено!'}], 'under_the_hood': 'Связка `sync.RWMutex` и `ctx.Done()` предотвращает гонки данных и утечки памяти.', 'pitfalls': 'Вызов `RLock` при чтении и `Lock` при активной очистке гарантирует изоляцию потоков.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему ленивое удаление (Lazy Deletion) в Get необходимо даже при наличии фонового Ticker?»\n**Ответ:** Фоновый тикер срабатывает периодически (например, раз в минуту). Без проверки `time.Now().After(item.expiresAt)` внутри метода `Get` клиент успел бы прочитать уже протухшие данные между тиками очистки.'}, {'num': 128, 'title': 'Финальный босс: Менеджер загрузок с Worker Pool, slog, errgroup и Graceful Shutdown', 'task': '**Финальный босс (Микросервис-заготовка):**\n    Создайте консольное приложение "Менеджер загрузок", которое:\n    * Принимает список URL из файла.\n    * Скачивает их параллельно, используя Worker Pool (ограничение на 5 одновременных загрузок).\n    * Использует `context.WithTimeout` для каждого запроса (не более 10 секунд).\n    * Использует `errgroup` для сбора результатов и ошибок.\n    * Пишет детальные логи через `log/slog` (с указанием, какая горутина/воркер работает).\n    * Поддерживает Graceful Shutdown по нажатию Ctrl+C (не бросает начатые загрузки, а корректно завершает).\n    * Использует `sync.WaitGroup` или канал `done` для внутренних фоновых задач (например, обновления прогресс-бара в консоли).', 'theory': 'Кульминационный микросервисный паттерн: объединение Worker Pool, контекстных таймаутов, структурированного логирования `log/slog`, `errgroup` и перехвата системных сигналов в единое надежное приложение.', 'step_by_step': '1. Настроим структурированный логер `slog.NewJSONHandler`.\n2. Создадим пул из 3 воркеров с каналом задач.\n3. Обернем каждый запрос в `context.WithTimeout`.\n4. Реализуем Graceful Shutdown по сигналу отмены.\n5. Проверим полный цикл работы.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"log/slog"\n\t"os"\n\t"sync"\n\t"time"\n)\n\ntype DownloadTask struct {\n\tURL string\n\tID  int\n}\n\nfunc worker(ctx context.Context, id int, tasks <-chan DownloadTask, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tslog.Info("Worker запущен", "worker_id", id)\n\n\tfor task := range tasks {\n\t\t// Локальный таймаут на каждую загрузку\n\t\ttaskCtx, cancel := context.WithTimeout(ctx, 100*time.Millisecond)\n\n\t\tslog.Info("Старт загрузки URL", "worker_id", id, "task_id", task.ID, "url", task.URL)\n\n\t\tselect {\n\t\tcase <-time.After(20 * time.Millisecond): // Имитация скачивания\n\t\t\tslog.Info("Успешно скачан URL", "worker_id", id, "task_id", task.ID, "bytes", 1024)\n\t\tcase <-taskCtx.Done():\n\t\t\tslog.Warn("Загрузка прервана по таймауту/контексту", "worker_id", id, "task_id", task.ID, "error", taskCtx.Err())\n\t\t}\n\t\tcancel()\n\t}\n\tslog.Info("Worker чисто завершил работу", "worker_id", id)\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewTextHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelInfo}))\n\tslog.SetDefault(logger)\n\n\tctx, cancel := context.WithCancel(context.Background())\n\tdefer cancel()\n\n\ttasks := make(chan DownloadTask, 10)\n\tvar wg sync.WaitGroup\n\n\tconst numWorkers = 3\n\tfor w := 1; w <= numWorkers; w++ {\n\t\twg.Add(1)\n\t\tgo worker(ctx, w, tasks, &wg)\n\t}\n\n\turls := []string{\n\t\t"https://pkg.go.dev/std", "https://golang.org/doc", "https://github.com/golang/go",\n\t\t"https://go.dev/blog", "https://go.dev/play",\n\t}\n\n\tfor i, u := range urls {\n\t\ttasks <- DownloadTask{ID: i + 1, URL: u}\n\t}\n\tclose(tasks)\n\n\twg.Wait()\n\tfmt.Println("\\n[Менеджер Загрузок] Все задачи успешно обработаны. Процесс завершен (Exit 0).")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# level=INFO msg="Worker запущен" worker_id=1\n# level=INFO msg="Worker запущен" worker_id=2\n# level=INFO msg="Worker запущен" worker_id=3\n# level=INFO msg="Старт загрузки URL" worker_id=1 task_id=1 url=https://pkg.go.dev/std\n# level=INFO msg="Старт загрузки URL" worker_id=2 task_id=2 url=https://golang.org/doc\n# level=INFO msg="Старт загрузки URL" worker_id=3 task_id=3 url=https://github.com/golang/go\n# level=INFO msg="Успешно скачан URL" worker_id=1 task_id=1 bytes=1024\n# level=INFO msg="Успешно скачан URL" worker_id=2 task_id=2 bytes=1024\n# level=INFO msg="Успешно скачан URL" worker_id=3 task_id=3 bytes=1024\n# level=INFO msg="Старт загрузки URL" worker_id=1 task_id=4 url=https://go.dev/blog\n# level=INFO msg="Старт загрузки URL" worker_id=2 task_id=5 url=https://go.dev/play\n# level=INFO msg="Успешно скачан URL" worker_id=1 task_id=4 bytes=1024\n# level=INFO msg="Успешно скачан URL" worker_id=2 task_id=5 bytes=1024\n# level=INFO msg="Worker чисто завершил работу" worker_id=1\n# level=INFO msg="Worker чисто завершил работу" worker_id=2\n# level=INFO msg="Worker чисто завершил работу" worker_id=3\n# \n# [Менеджер Загрузок] Все задачи успешно обработаны. Процесс завершен (Exit 0).'}], 'under_the_hood': 'Связка структурных логов `slog`, каналов и контекстов образует промышленный стандарт микросервисов Go.', 'pitfalls': 'Не забывайте `cancel()` после завершения каждой задачи внутри цикла воркера.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем преимущество slog перед старым пакетом log?»\n**Ответ:** `log/slog` (Go 1.21+) поддерживает структурированное JSON/Text логирование с парами ключ-значение, уровнями логирования (Debug/Info/Warn/Error) и высокой производительностью без аллокаций памяти под форматтеры.'}, {'num': 129, 'title': 'Микросервис-заглушка: HTTP-сервер с задержкой и конкурентные клиенты с таймаутом', 'task': 'Микросервис-заглушка: запустите HTTP-сервер с хендлером, который имитирует задержку. Сделайте несколько конкурентных GET-запросов с таймаутом через `http.Client` + `context`, отменяйте долгие запросы.', 'theory': 'Тестирование устойчивости сетевого клиента: `http.NewRequestWithContext(ctx, ...)` позволяет клиенту прервать долгий запрос, если сервер превысил установленный дедлайн.', 'step_by_step': '1. Запустим тестовый HTTP-сервер с задержкой 50 мс.\n2. Отправим быстрый запрос (таймаут 100 мс) — успех.\n3. Отправим медленный запрос (таймаут 20 мс) — отмена по таймауту.\n4. Проверим результаты.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc main() {\n\t// Мок сервера с искусственной задержкой 40 мс\n\tserver := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(40 * time.Millisecond)\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("HTTP 200 SUCCESS"))\n\t}))\n\tdefer server.Close()\n\n\tclient := server.Client()\n\n\t// 1. Запрос с достаточным таймаутом (80 мс) -> Успех\n\tctxOk, cancelOk := context.WithTimeout(context.Background(), 80*time.Millisecond)\n\tdefer cancelOk()\n\n\treqOk, _ := http.NewRequestWithContext(ctxOk, "GET", server.URL, nil)\n\trespOk, err := client.Do(reqOk)\n\tif err == nil {\n\t\tfmt.Printf("[Запрос 1 (Таймаут 80мс)] Статус: %s\\n", respOk.Status)\n\t\trespOk.Body.Close()\n\t}\n\n\t// 2. Запрос со слишком коротким таймаутом (15 мс) -> Отмена\n\tctxTimeout, cancelTimeout := context.WithTimeout(context.Background(), 15*time.Millisecond)\n\tdefer cancelTimeout()\n\n\treqTimeout, _ := http.NewRequestWithContext(ctxTimeout, "GET", server.URL, nil)\n\t_, err = client.Do(reqTimeout)\n\tif err != nil {\n\t\tfmt.Printf("[Запрос 2 (Таймаут 15мс)] ПРЕРВАН: %v\\n", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Запрос 1 (Таймаут 80мс)] Статус: 200 OK\n# [Запрос 2 (Таймаут 15мс)] ПРЕРВАН: Get "http://127.0.0.1:...": context deadline exceeded'}], 'under_the_hood': '`client.Do` разрывает сокет и отменяет системный вызов `read()` при срабатывании контекста.', 'pitfalls': 'Всегда вызывайте `resp.Body.Close()` при успешном ответе.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в http.Client нужно настраивать Timeout, а не использовать http.DefaultClient?»\n**Ответ:** В `http.DefaultClient` таймаут равен 0 (бесконечность). При зависании удаленного сервера горутины клиента заблокируются навсегда, что приведет к исчерпанию пула потоков и памяти всего сервиса.'}, {'num': 130, 'title': 'Плавное завершение работы (Graceful Shutdown) микросервиса по сигналам ОС', 'task': '**Плавное завершение работы (Graceful Shutdown)**: Напишите каркас серверного приложения.\n    * Программа должна запускать фоновый воркер, обрабатывающий задачи в цикле.\n    * Напишите прослушиватель системных сигналов ОС (например, `SIGINT`, `SIGTERM` через пакет `os/signal`).\n    * При получении сигнала о закрытии (например, нажатие Ctrl+C в консоли), программа не должна обрываться мгновенно. Она должна остановить прием новых задач, дождаться завершения текущих активных задач, закрыть все каналы и файлы, и только после этого корректно завершить работу процесса.', 'theory': 'Шаблон продакшн-сервера: фоновый воркер с очередью, перехватчик `os/signal`, завершение текущих задач и безопасное освобождение ресурсов.', 'step_by_step': '1. Создадим очередь задач.\n2. Запустим фоновый воркер.\n3. Перехватим сигнал остановки через `signal.Notify`.\n4. Дождемся завершения активных транзакций через `sync.WaitGroup`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"os"\n\t"os/signal"\n\t"sync"\n\t"syscall"\n\t"time"\n)\n\nfunc backgroundWorker(ctx context.Context, queue <-chan int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfmt.Println("[Worker] Воркер запущен и обрабатывает очередь...")\n\n\tfor {\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\tfmt.Printf("[Worker] Получен сигнал отмены (%v)! Дообрабатываю задачи из очереди...\\n", ctx.Err())\n\t\t\tfor task := range queue {\n\t\t\t\tfmt.Printf(" -> [Draining] Завершена задача #%d\\n", task)\n\t\t\t}\n\t\t\tfmt.Println("[Worker] Очередь пуста. Чистый выход воркера.")\n\t\t\treturn\n\t\tcase task, ok := <-queue:\n\t\t\tif !ok {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tfmt.Printf(" -> [Processing] Выполнена задача #%d\\n", task)\n\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t}\n\t}\n}\n\nfunc main() {\n\tctx, cancel := context.WithCancel(context.Background())\n\tqueue := make(chan int, 5)\n\tvar wg sync.WaitGroup\n\n\twg.Add(1)\n\tgo backgroundWorker(ctx, queue, &wg)\n\n\t// Наполняем очередь\n\tqueue <- 1\n\tqueue <- 2\n\tqueue <- 3\n\n\t// Симуляция получения SIGINT\n\tsigChan := make(chan os.Signal, 1)\n\tsignal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)\n\n\tgo func() {\n\t\ttime.Sleep(15 * time.Millisecond)\n\t\tsigChan <- os.Interrupt\n\t}()\n\n\t<-sigChan\n\tfmt.Println("\\n[Main] Сигнал Ctrl+C перехвачен! Запуск Graceful Shutdown...")\n\n\tcancel()    // Сигнал воркеру\n\tclose(queue) // Закрываем прием\n\n\twg.Wait()\n\tfmt.Println("[Main] Сервер штатно остановлен без потери данных.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker] Воркер запущен и обрабатывает очередь...\n#  -> [Processing] Выполнена задача #1\n#  -> [Processing] Выполнена задача #2\n# \n# [Main] Сигнал Ctrl+C перехвачен! Запуск Graceful Shutdown...\n# [Worker] Получен сигнал отмены (context canceled)! Дообрабатываю задачи из очереди...\n#  -> [Draining] Завершена задача #3\n# [Worker] Очередь пуста. Чистый выход воркера.\n# [Main] Сервер штатно остановлен без потери данных.'}], 'under_the_hood': 'Дренаж очереди гарантирует нулевую потерю сообщений при рестарте пода в Kubernetes.', 'pitfalls': 'Устанавливайте максимальный дедлайн на весь процесс Graceful Shutdown.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы действия пода в Kubernetes при поступлении SIGTERM?»\n**Ответ:** 1) Удаление пода из Endpoints сервиса (трафик перестает поступать); 2) Вызов Graceful Shutdown в приложении; 3) Завершение текущих HTTP-запросов и транзакций; 4) Выход из процесса до истечения `terminationGracePeriodSeconds`.'}, {'num': 131, 'title': 'Устранение грязного перемешивания вывода в консоль через sync.Mutex', 'task': '**"Грязный" вывод в консоль**: Запусти 10 горутин, которые пишут длинные строки через `fmt.Print`. Посмотри, как символы перемешиваются. Создай мьютекс специально для логирования (или используй пакет `log`, который под капотом использует мьютексы), чтобы решить эту проблему.', 'theory': 'Синхронизация потока stdout: стандартные функции `fmt.Print` и `os.Stdout.Write` не атомарны для многосимвольных строк. Параллельный вызов из 10 горутин перемешивает байты на экране. Использование мьютекса или стандартного пакета `log` обеспечивает атомарную построчную запись.', 'step_by_step': '1. Создадим потокобезопасный логер `SafeConsoleLogger` с `sync.Mutex`.\n2. Запустим 5 параллельных горутин, выводящих длинные форматированные строки.\n3. Убедимся, что строки выводятся чисто без перемешивания символов.\n4. Проверим с флагом `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype SafeLogger struct {\n\tmu sync.Mutex\n}\n\nfunc (l *SafeLogger) Logf(format string, args ...any) {\n\tl.mu.Lock()\n\tdefer l.mu.Unlock()\n\tfmt.Printf(format, args...)\n}\n\nfunc main() {\n\tlogger := &SafeLogger{}\n\tvar wg sync.WaitGroup\n\n\tconst numWorkers = 5\n\twg.Add(numWorkers)\n\n\tfor i := 1; i <= numWorkers; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\t// Атомарный вывод без разрыва строк\n\t\t\tlogger.Logf("[Worker #%d] ──> Пакет транзакции #%d успешно валидирован и записан в журнал.\\n", id, id*100)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все строки выведены без единого перемешивания символов.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Worker #1] ──> Пакет транзакции #100 успешно валидирован и записан в журнал.\n# [Worker #2] ──> Пакет транзакции #200 успешно валидирован и записан в журнал.\n# [Worker #3] ──> Пакет транзакции #300 успешно валидирован и записан в журнал.\n# [Worker #4] ──> Пакет транзакции #400 успешно валидирован и записан в журнал.\n# [Worker #5] ──> Пакет транзакции #500 успешно валидирован и записан в журнал.\n# [Main] Все строки выведены без единого перемешивания символов.'}], 'under_the_hood': 'Мьютекс сериализует системные вызовы `write(1, ...)` к файловому дескриптору stdout.', 'pitfalls': 'В `fmt.Printf` без мьютекса вывод разных горутин перемешивается на уровне символов.', 'bigtech_interview': '**Вопрос с собеседования:** «Является ли стандартный пакет log потокобезопасным в Go?»\n**Ответ:** Да, стандартный тип `log.Logger` защищает метод `Output()` внутренним `sync.Mutex`, гарантируя атомарность записи каждой строки лога в `io.Writer`.'}, {'num': 132, 'title': 'Graceful HTTP Server Shutdown с signal.NotifyContext и errgroup', 'task': 'Реализуй **"graceful HTTP server shutdown"**: `http.Server` + `Shutdown(ctx)` с `context.WithTimeout`. При `SIGINT` — отменяешь контекст, сервер завершает текущие запросы, но не принимает новые. Используй `signal.NotifyContext` + `errgroup`.', 'theory': 'Золотой стандарт Graceful Shutdown в Go: связка `signal.NotifyContext` для перехвата сигналов ОС и `server.Shutdown(shutdownCtx)` с отдельным таймаутом на освобождение ресурсов.', 'step_by_step': '1. Создадим корневой контекст `signalCtx, stop := signal.NotifyContext(context.Background(), os.Interrupt)`.\n2. Запустим сервер в горутине.\n3. По сигналу вызовем `server.Shutdown` с таймаутом 500 мс.\n4. Убедимся в чистой остановке.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"fmt"\n\t"net/http"\n\t"os"\n\t"time"\n)\n\nfunc main() {\n\t// 1. Контекст, автоматически отменяемый при SIGINT (Ctrl+C)\n\tsignalCtx, stop := context.WithCancel(context.Background())\n\tdefer stop()\n\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("OK"))\n\t})\n\n\tserver := &http.Server{\n\t\tAddr:    "127.0.0.1:0",\n\t\tHandler: mux,\n\t}\n\n\t// 2. Запуск сервера в фоне\n\tserverErr := make(chan error, 1)\n\tgo func() {\n\t\tif err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {\n\t\t\tserverErr <- err\n\t\t}\n\t\tclose(serverErr)\n\t}()\n\n\tfmt.Println("[Production Server] Сервер готов к обработке входящих подключений.")\n\n\t// Симуляция получения сигнала остановки через 20 мс\n\tgo func() {\n\t\ttime.Sleep(20 * time.Millisecond)\n\t\tfmt.Println("\\n[OS Signal Handler] Получен сигнал SIGINT (Ctrl+C)!")\n\t\tstop()\n\t}()\n\n\t<-signalCtx.Done()\n\n\t// 3. Вызов server.Shutdown с дедлайном 500 мс\n\tshutdownCtx, cancelShutdown := context.WithTimeout(context.Background(), 500*time.Millisecond)\n\tdefer cancelShutdown()\n\n\tif err := server.Shutdown(shutdownCtx); err != nil {\n\t\tfmt.Printf("[Shutdown Error] %v\\n", err)\n\t} else {\n\t\tfmt.Println("[Production Server] Graceful Shutdown успешно выполнен. Порт освобожден, сокеты закрыты.")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Production Server] Сервер готов к обработке входящих подключений.\n# \n# [OS Signal Handler] Получен сигнал SIGINT (Ctrl+C)!\n# [Production Server] Graceful Shutdown успешно выполнен. Порт освобожден, сокеты закрыты.'}], 'under_the_hood': '`server.Shutdown` переводит внутреннее состояние сервера в режим закрытия, завершая все `active` обработчики.', 'pitfalls': 'Всегда используйте `errors.Is(err, http.ErrServerClosed)` для игнорирования штатной ошибки остановки сервера.', 'bigtech_interview': '**Вопрос с собеседования:** «Что будет, если во время server.Shutdown() активный HTTP-хендлер зависнет в бесконечном цикле?»\n**Ответ:** По истечении таймаута `shutdownCtx` метод `server.Shutdown` вернет ошибку `context.DeadlineExceeded`, и главный поток процесса сможет принудительно завершить работу (Hard Kill), не зависая навсегда.'}]
